src/components/business/BusinessEmptySta:
/**
 * BusinessEmptyState — CB102 welcome for every golf business (biz-welcome.html).
 * Supersedes V3. Renders inside MyBusinessesPage → ManagePageShell only when the
 * member has no businesses.
 *
 * - The "Your insights" card is a FIXED SAMPLE (SAMPLE_INSIGHTS), labelled
 *   Sample. It fetches nothing and must never show real data.
 * - "On clbhouz today" reads get_platform_reach_v2 (rounds, reviews only; no
 *   golfers row). A failed read hides the card and its footnote.
 * - Amber appears only inside the real VerifiedBadge. Green only for deltas.
 * - Nothing implies verified businesses rank higher in discovery.
 */
import type React from 'react';
import { useTranslation } from 'react-i18next';
import { ArrowRight, Search, MessageSquare, MessageCircle, BarChart3 } from 'lucide-react';
import { usePlatformReachV2 } from '@/hooks/usePlatformReachV2';
import { VerifiedBadge } from '@/components/ui/VerifiedBadge';
import { Skeleton } from '@/components/ui/skeleton';

const CANVAS = '#0B0B0D';
const CARD = '#17171B';
const INSET = '#1E1E23';
const HAIR = 'rgba(255,255,255,0.08)';
const INK = '#F8FAFC';
const MUTE = 'rgba(248,250,252,0.62)';
const DIM = 'rgba(248,250,252,0.42)';
const GREEN = '#34D399';

export const SAMPLE_INSIGHTS = {
  funnel: [
    { value: 46, label: 'golfers saw your posts' },
    { value: 12, label: 'opened your profile' },
    { value: 5, label: 'new followers' },
  ],
  bands: [
    { label: 'Plus–5', pct: 50, count: 3 },
    { label: '6–12', pct: 100, count: 6 },
    { label: '13–20', pct: 67, count: 4 },
    { label: '21+', pct: 17, count: 1 },
  ],
} as const;

const GETS = [
  { Icon: Search, title: 'A profile golfers can find', line: 'In search and the directory, next to the courses golfers already browse.' },
  { Icon: MessageSquare, title: 'Posts in the Clubhouse feed', line: 'News, offers and events go straight to the golfers who follow you.' },
  { Icon: MessageCircle, title: 'Golfers can message you', line: 'One tap from your profile to a conversation.' },
  { Icon: BarChart3, title: 'Insights from real golfers', line: 'Who saw you, who followed, and how they play.' },
];

const TYPES = [
  ['Golf clubs', 'Also get every round on your courses read hole by hole, and reply to your course reviews.'],
  ['Ranges, academies, coaches and colleges', 'Show golfers your sessions and teams, and see the handicaps of who follows you.'],
  ['Shops and club fitters', 'Put new stock and fitting days in front of golfers who follow you.'],
  ['Resorts and hotels', 'Show your courses and stays to golfers who follow you.'],
  ['Restaurants, cafes and bars', 'Be found by golfers on their way to or from a round.'],
  ['Brands and creators', 'Post to golfers and see who engages, band by band.'],
];

/** Grouped figures, tolerant of a malformed language tag. */
function fmt(n: number, locale: string): string {
  try {
    return n.toLocaleString(locale);
  } catch {
    return n.toLocaleString('en');
  }
}

const kicker: React.CSSProperties = { fontSize: 10.5, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase', color: MUTE };
const rightLabel: React.CSSProperties = { fontSize: 10.5, fontWeight: 800, letterSpacing: '0.12em', textTransform: 'uppercase', color: DIM, whiteSpace: 'nowrap' };
const cardStyle: React.CSSProperties = { background: CARD, border: `1px solid ${HAIR}`, borderRadius: 18, padding: 16, marginBottom: 14 };
const titleStyle: React.CSSProperties = { fontSize: 17, fontWeight: 700, letterSpacing: '-0.01em', lineHeight: 1.3, color: INK, margin: 0 };
const rowTitle: React.CSSProperties = { display: 'block', fontSize: 15, fontWeight: 600, lineHeight: 1.3, color: INK };
const rowLine: React.CSSProperties = { display: 'block', fontSize: 13, lineHeight: 1.4, color: MUTE, marginTop: 3 };

function CreatePill({ onClick }: { onClick: () => void }) {
  return (
    <button
      type="button"
      data-create-pill=""
      onClick={onClick}
      style={{
        display: 'inline-flex', alignItems: 'center', height: 42, padding: '0 18px 0 20px',
        borderRadius: 999, background: INK, color: CANVAS, fontSize: 15, fontWeight: 600,
        letterSpacing: '-0.005em', border: 'none', cursor: 'pointer',
      }}
    >
      Create a business profile
      <ArrowRight size={16} style={{ marginLeft: 8 }} aria-hidden />
    </button>
  );
}

function Card({ id, children, style }: { id: string; children: React.ReactNode; style?: React.CSSProperties }) {
  return <section data-card={id} style={{ ...cardStyle, ...style }}>{children}</section>;
}

function Figures({ locale }: { locale: string }) {
  const { data, isLoading, isError } = usePlatformReachV2();
  if (isError) return null;
  const rows = data
    ? [
        { label: 'Rounds read hole by hole', total: data.rounds, delta: data.roundsDelta },
        { label: 'Course reviews', total: data.reviews, delta: data.reviewsDelta },
      ]
    : null;
  return (
    <>
      <Card id="figures" style={{ marginBottom: 8 }}>
        <div style={{ ...kicker, marginBottom: 10 }}>On clbhouz today</div>
        {isLoading || !rows ? (
          <div data-figures-loading="" style={{ display: 'grid', gridTemplateColumns: 'minmax(0, 1fr)', gap: 12, padding: '11px 0' }}>
            <Skeleton className="h-4 w-2/3 rounded" />
            <Skeleton className="h-4 w-1/2 rounded" />
          </div>
        ) : (
          rows.map((r, i) => (
            <div
              key={r.label}
              data-figure-row=""
              style={{
                display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', padding: '11px 0',
                fontSize: 15, color: INK, borderTop: i === 1 ? `1px solid ${HAIR}` : undefined,
              }}
            >
              <span>{r.label}</span>
              <span style={{ fontVariantNumeric: 'tabular-nums', whiteSpace: 'nowrap' }}>
                {fmt(r.total, locale)}
                {r.delta > 0 && (
                  <span data-delta="" style={{ color: GREEN, fontSize: 13.5, marginLeft: 8 }}>+{fmt(r.delta, locale)}</span>
                )}
              </span>
            </div>
          ))
        )}
      </Card>
      <p data-figures-footnote="" style={{ fontSize: 12.5, lineHeight: 1.45, color: DIM, margin: '2px 4px 14px' }}>
        Green figures are the last 30 days.
      </p>
    </>
  );
}

export function BusinessEmptyState({ onCreate }: { onCreate: () => void }) {
  const { i18n } = useTranslation();
  const locale = i18n?.language || 'en';

  return (
    <div style={{ padding: '4px 0 0', background: CANVAS, color: INK }}>
      {/* 1. Opening */}
      <div data-card="opening" style={{ padding: '6px 2px 22px' }}>
        <div style={kicker}>Golf businesses on clbhouz</div>
        <h2 style={{ fontSize: 27, fontWeight: 700, letterSpacing: '-0.02em', lineHeight: 1.16, marginTop: 10, color: INK }}>
          Reach golfers who track every round.<span style={{ color: MUTE }}> And know exactly who they are.</span>
        </h2>
        <p style={{ fontSize: 14.5, lineHeight: 1.45, color: MUTE, marginTop: 10 }}>
          For every golf business: clubs, ranges, academies, coaches, shops, fitters, resorts, hotels, restaurants and brands. Free, and it takes about a minute.
        </p>
        <div style={{ marginTop: 18 }}><CreatePill onClick={onCreate} /></div>
      </div>

      {/* 2. What every business gets */}
      <Card id="gets">
        <div style={{ ...kicker, marginBottom: 10 }}>What every business gets</div>
        {GETS.map(({ Icon, title, line }) => (
          <div key={title} data-row="" style={{ display: 'grid', gridTemplateColumns: '34px minmax(0,1fr)', gap: 12, padding: '12px 0', borderTop: `1px solid ${HAIR}`, alignItems: 'start' }}>
            <span style={{ width: 34, height: 34, borderRadius: 10, background: INSET, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
              <Icon size={17} strokeWidth={1.9} color="rgba(248,250,252,0.85)" aria-hidden />
            </span>
            <div><b style={rowTitle}>{title}</b><span style={rowLine}>{line}</span></div>
          </div>
        ))}
      </Card>

      {/* 3. Your insights — fixed sample, fetches nothing */}
      <Card id="sample">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: 12, marginBottom: 10 }}>
          <div style={kicker}>Your insights</div>
          <div style={rightLabel}>Sample</div>
        </div>
        <p style={titleStyle}>Know who follows you, by handicap.<span style={{ color: MUTE }}> No other platform can tell you.</span></p>
        <p style={{ fontSize: 13.5, lineHeight: 1.45, color: MUTE, marginTop: 6 }}>
          Handicaps come from each golfer's own WHS record, so the bands are real, not guessed.
        </p>
        <div style={{ display: 'flex', gap: 8, marginTop: 14 }}>
          {SAMPLE_INSIGHTS.funnel.map((f) => (
            <div key={f.label} data-funnel="" style={{ flex: 1, background: INSET, borderRadius: 13, padding: '11px 10px' }}>
              <b data-value="" style={{ display: 'block', fontSize: 20, fontWeight: 700, letterSpacing: '-0.01em', fontVariantNumeric: 'tabular-nums', color: INK }}>{f.value}</b>
              <span style={{ display: 'block', fontSize: 11.5, lineHeight: 1.3, color: MUTE, marginTop: 3 }}>{f.label}</span>
            </div>
          ))}
        </div>
        <div style={{ ...rightLabel, margin: '16px 0 4px' }}>Your golfers</div>
        {SAMPLE_INSIGHTS.bands.map((b) => (
          <div key={b.label} data-band="" style={{ display: 'grid', gridTemplateColumns: '62px minmax(0,1fr) 26px', alignItems: 'center', gap: 10, padding: '6px 0', fontSize: 13, fontVariantNumeric: 'tabular-nums' }}>
            <span style={{ color: MUTE }}>{b.label}</span>
            <span style={{ height: 8, borderRadius: 4, background: 'rgba(255,255,255,0.06)', overflow: 'hidden' }}>
              <span style={{ display: 'block', height: '100%', width: `${b.pct}%`, background: 'rgba(248,250,252,0.78)', borderRadius: 4 }} />
            </span>
            <span data-count="" style={{ textAlign: 'right', fontWeight: 600, color: INK }}>{b.count}</span>
          </div>
        ))}
      </Card>

      {/* 4. Built for your kind of business */}
      <Card id="types">
        <div style={{ ...kicker, marginBottom: 10 }}>Built for your kind of business</div>
        {TYPES.map(([title, line]) => (
          <div key={title} data-row="" style={{ padding: '12px 0', borderTop: `1px solid ${HAIR}` }}>
            <b style={rowTitle}>{title}</b><span style={rowLine}>{line}</span>
          </div>
        ))}
      </Card>

      {/* 5. How it works */}
      <Card id="steps">
        <div style={{ ...kicker, marginBottom: 10 }}>How it works</div>
        {[
          { n: 1, title: <>Create a profile</>, line: 'Free, about a minute. A name and a category.' },
          { n: 2, title: <>Post and grow</>, line: 'Golfers find you, follow you and message you. Your insights fill in as they do.' },
          {
            n: 3,
            title: <>Get verified<span style={{ marginLeft: 4, display: 'inline-flex', verticalAlign: 'middle' }}><VerifiedBadge size="sm" /></span></>,
            line: 'Free, checked by a person. Golf clubs also claim their courses here.',
          },
        ].map((s) => (
          <div key={s.n} data-step="" style={{ display: 'grid', gridTemplateColumns: '28px minmax(0,1fr)', gap: 12, padding: '12px 0', borderTop: `1px solid ${HAIR}`, alignItems: 'start' }}>
            <span style={{ width: 26, height: 26, borderRadius: '50%', border: '1px solid rgba(255,255,255,0.18)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 12.5, fontWeight: 700, color: INK }}>{s.n}</span>
            <div><b style={rowTitle}>{s.title}</b><span style={rowLine}>{s.line}</span></div>
          </div>
        ))}
      </Card>

      {/* 6. On clbhouz today */}
      <Figures locale={locale} />

      {/* 7. Foot */}
      <div data-card="foot" style={{ textAlign: 'center', paddingTop: 6 }}>
        <CreatePill onClick={onCreate} />
        <p style={{ fontSize: 12.5, color: DIM, marginTop: 10 }}>Free. About a minute.</p>
      </div>
    </div>
  );
}

export default BusinessEmptyState;

src/components/business/BusinessFollower:
/**
 * CB115 — "Their followers" for every non-club business, after
 * BusinessNearbyCourses (or BusinessYouCard when there is no nearby card).
 * One read: get_business_follower_golf. Every privacy floor (10 handicaps for
 * the mix, 3 golfers per course, 3 courses max) lives in the function; the
 * client renders what it returns and recomputes nothing. Nothing renders until
 * the read settles; a failed read or null result means no card (state D).
 * The viewer's band comes from useWhsConnection → useHandicapTrend.current.
 */
import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { supabase } from '@/integrations/supabase/client';
import { formatNumber } from '@/i18n/format';
import { shortCourseName } from '@/features/courses/_shared/courseLabel';
import { CourseImageFallback } from '@/components/whs/CourseImageFallback';
import { useHandicapTrend, useWhsConnection } from '@/lib/whs/hooks';

const T = {
  card: '#17171B', ink: '#F8FAFC', mute: 'rgba(248,250,252,0.62)', dim: 'rgba(248,250,252,0.42)',
  hair: 'rgba(255,255,255,0.08)', track: 'rgba(255,255,255,0.06)', fill: 'rgba(248,250,252,0.38)',
} as const;
const TAB = { fontVariantNumeric: 'tabular-nums' } as const;

export type BandKey = 'under5' | 'b5' | 'b10' | 'b15' | 'b20';
export const BANDS: Array<{ key: BandKey; label: string }> = [
  { key: 'under5', label: 'Under 5' }, { key: 'b5', label: '5\u201310' }, { key: 'b10', label: '10\u201315' },
  { key: 'b15', label: '15\u201320' }, { key: 'b20', label: '20+' },
];
export interface FollowerGolf {
  handicap_count: number | null;
  bands: Record<BandKey, number> | null;
  courses: Array<{ course_id: string; name: string; thumbnail_image: string | null; rounds: number; golfers: number }>;
}

/** Plus handicaps (negative) fall in Under 5. */
export function bandFor(h: number | null | undefined): BandKey | null {
  if (h == null || !Number.isFinite(h)) return null;
  if (h < 5) return 'under5';
  if (h < 10) return 'b5';
  if (h < 15) return 'b10';
  if (h < 20) return 'b15';
  return 'b20';
}
export const bandPct = (count: number, total: number) => (total > 0 ? Math.round((count / total) * 100) : 0);

export function useBusinessFollowerGolf(businessId: string | undefined, enabled: boolean) {
  return useQuery({
    queryKey: ['business-follower-golf', businessId ?? null],
    enabled: enabled && !!businessId,
    staleTime: 60_000,
    queryFn: async (): Promise<FollowerGolf | null> => {
      const { data, error } = await (supabase as unknown as { rpc: (n: string, a: unknown) => Promise<{ data: unknown; error: unknown }> })
        .rpc('get_business_follower_golf', { p_business_id: businessId });
      if (error) throw error;
      if (!data || typeof data !== 'object') return null;
      const d = data as Partial<FollowerGolf>;
      return { handicap_count: d.handicap_count ?? null, bands: d.bands ?? null, courses: Array.isArray(d.courses) ? d.courses : [] };
    },
  });
}

export function BusinessFollowersCard({ isClub, businessId, viewerId }: { isClub: boolean; businessId: string; viewerId?: string }) {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const q = useBusinessFollowerGolf(businessId, !isClub);
  const { data: connection } = useWhsConnection(isClub ? undefined : viewerId);
  const { data: trend } = useHandicapTrend((connection as { id?: string } | null | undefined)?.id);
  if (isClub || q.isLoading || q.isError || !q.data) return null;
  const { handicap_count, bands, courses } = q.data;
  const showMix = bands != null && handicap_count != null && handicap_count > 0;
  const showCourses = courses.length > 0;
  if (!showMix && !showCourses) return null;
  const mine = bandFor((trend as { current?: number | null } | null | undefined)?.current ?? null);

  return (
    <section data-business-followers style={{ background: T.card, border: `1px solid ${T.hair}`, borderRadius: 18, padding: 16, margin: '14px 16px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: 12, marginBottom: 10 }}>
        <span style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase', color: T.mute }}>
          {t('business.followers.kicker', { defaultValue: 'Their followers' })}
        </span>
        {handicap_count != null && (
          <span data-followers-count style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: '0.12em', textTransform: 'uppercase', color: T.dim, whiteSpace: 'nowrap' }}>
            {t('business.followers.withHandicap', { count: handicap_count, n: formatNumber(handicap_count), defaultValue: `${formatNumber(handicap_count)} with a handicap` })}
          </span>
        )}
      </div>

      {showMix && (
        <div data-followers-mix>
          {BANDS.map(({ key, label }) => {
            const n = bands![key] ?? 0;
            const pct = bandPct(n, handicap_count!);
            const me = mine === key;
            return (
              <div key={key} data-band={key} data-band-me={me ? '' : undefined}
                style={{ display: 'grid', gridTemplateColumns: '70px minmax(0,1fr) 40px', alignItems: 'center', gap: 10, padding: '5px 0', fontSize: 12.5, ...TAB }}>
                <span style={{ color: me ? T.ink : T.mute, fontWeight: me ? 600 : undefined, whiteSpace: 'nowrap' }}>
                  {t(`business.followers.band.${key}`, { defaultValue: label })}
                  {me && (
                    <span data-band-you style={{ fontSize: 9, fontWeight: 800, letterSpacing: '0.1em', textTransform: 'uppercase', color: T.dim, marginLeft: 5 }}>
                      {t('business.followers.you', { defaultValue: 'You' })}
                    </span>
                  )}
                </span>
                <span style={{ height: 6, borderRadius: 3, background: T.track, overflow: 'hidden' }}>
                  <i data-band-fill style={{ display: 'block', height: '100%', borderRadius: 3, width: `${(n / handicap_count!) * 100}%`, background: me ? T.ink : T.fill }} />
                </span>
                <span data-band-value style={{ textAlign: 'right', color: me ? T.ink : T.mute, fontWeight: me ? 600 : undefined }}>{pct}%</span>
              </div>
            );
          })}
        </div>
      )}

      {showCourses && (
        <div data-followers-courses style={showMix ? { marginTop: 16, paddingTop: 10, borderTop: `1px solid ${T.hair}` } : { marginTop: -8 }}>
          <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: '0.12em', textTransform: 'uppercase', color: T.dim, marginBottom: 8 }}>
            {t('business.followers.wherePlay', { defaultValue: 'Where they play most' })}
          </div>
          {courses.map((c, i) => (
            <button key={c.course_id} type="button" data-followers-course={c.course_id} onClick={() => navigate(`/courses/${c.course_id}`)}
              style={{ display: 'flex', alignItems: 'center', gap: 12, width: '100%', padding: '11px 0', background: 'transparent', border: 0,
                borderTop: `1px solid ${T.hair}`, textAlign: 'left', cursor: 'pointer', color: T.ink }}>
              <span style={{ position: 'relative', width: 40, height: 40, borderRadius: 12, overflow: 'hidden', flex: 'none' }}>
                {c.thumbnail_image
                  ? <img src={c.thumbnail_image} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
                  : <CourseImageFallback />}
              </span>
              <span style={{ flex: 1, minWidth: 0 }}>
                <span style={{ display: 'block', fontSize: 14.5, fontWeight: 600, color: T.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                  {shortCourseName(c.name)}
                </span>
                <span data-followers-meta style={{ display: 'block', marginTop: 2, fontSize: 12.5, color: T.mute, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', ...TAB }}>
                  {i === 0
                    ? t('business.followers.firstRounds', { count: c.rounds, n: formatNumber(c.rounds), defaultValue: c.rounds === 1 ? '1 of their rounds in the last 12 months' : `${formatNumber(c.rounds)} of their rounds in the last 12 months` })
                    : t('business.followers.rounds', { count: c.rounds, n: formatNumber(c.rounds), defaultValue: c.rounds === 1 ? '1 round' : `${formatNumber(c.rounds)} rounds` })}
                </span>
              </span>
              <span style={{ color: T.dim, flex: 'none' }}>›</span>
            </button>
          ))}
        </div>
      )}

      <p data-followers-foot style={{ margin: '12px 0 0', fontSize: 12, lineHeight: 1.45, color: T.dim }}>
        {showCourses
          ? t('business.followers.footCourses', { defaultValue: 'From followers who show their handicap publicly. A course appears once 3 of them have played it.' })
          : t('business.followers.footMix', { defaultValue: 'From followers who show their handicap publicly.' })}
      </p>
    </section>
  );
}

src/components/business/BusinessNearbyCo:
/**
 * CB114 — "Courses nearby" for the five nearby categories (non-club only),
 * after BusinessYouCard. Courses come from useBusinessNearbyCounts (the hero's
 * query and key, so "All N" equals the hero's Courses near); figures from
 * useNearbyCourseStats (key shared with BusinessYouCard). Nothing renders until
 * both settle; a failed nearby read means no card; a failed stats read keeps
 * the card with distance-only meta lines and no foot.
 */
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { formatNumber } from '@/i18n/format';
import { shortCourseName } from '@/features/courses/_shared/courseLabel';
import { NEARBY_CATEGORIES } from '@/lib/business/businessHero';
import { useBusinessNearbyCounts, type NearbyCourse } from '@/hooks/useBusinessNearbyCounts';
import { useNearbyCourseStats, type NearbyCourseStat } from '@/hooks/useNearbyCourseStats';
import { CourseImageFallback } from '@/components/whs/CourseImageFallback';
import { BottomSheet } from '@/components/ui/BottomSheet';
import { scrollElementIntoView } from '@/lib/getScrollParent';

const T = {
  card: '#17171B', ink: '#F8FAFC', mute: 'rgba(248,250,252,0.62)',
  dim: 'rgba(248,250,252,0.42)', hair: 'rgba(255,255,255,0.08)', chip: 'rgba(255,255,255,0.2)',
} as const;
const TAB = { fontVariantNumeric: 'tabular-nums' } as const;

/** km → "1.2 mi". */
export const milesLabel = (km: number) => `${(km / 1.609344).toFixed(1)} mi`;

/** "+14.6", "−1.4" (U+2212) or "Level" at 0.0. */
export function playsLabel(avg: number): string {
  const r = Math.round(avg * 10) / 10;
  if (r === 0) return 'Level';
  return r > 0 ? `+${r.toFixed(1)}` : `\u2212${Math.abs(r).toFixed(1)}`;
}

type Tr = (key: string, o: { count?: number; n?: string; defaultValue: string }) => string;
/** English fallback for pure callers; components pass their own t (CB115 tidy). */
const enTr: Tr = (_k, o) => o.defaultValue.replace('{{n}}', o.n ?? '');

/** Rounds-count copy as i18n keys, plurals by count (CB115 tidy). */
export function roundsLabel(n: number, tr: Tr = enTr): string {
  if (n <= 0) return tr('business.nearby.noRounds', { defaultValue: 'No rounds yet' });
  if (n === 1) return tr('business.nearby.rounds', { count: 1, n: formatNumber(1), defaultValue: '1 round' });
  return tr('business.nearby.rounds', { count: n, n: formatNumber(n), defaultValue: `${formatNumber(n)} rounds` });
}

/** Meta parts; stats null = failed or never-run read → distance only. */
export function metaLine(c: NearbyCourse, s: NearbyCourseStat | null | undefined, statsFailed: boolean, tr: Tr = enTr): { line: string; plays: string | null } {
  const parts: string[] = [];
  if (c.distanceKm != null) parts.push(milesLabel(c.distanceKm));
  let plays: string | null = null;
  if (!statsFailed) {
    const n = s?.rounds_tracked ?? 0;
    if (n >= 3) {
      if (s?.avg_over_par != null) { plays = playsLabel(s.avg_over_par); parts.push(plays); }
    }
    parts.push(roundsLabel(n, tr));
  }
  return { line: parts.join(' \u00B7 '), plays };
}

function Row({ c, s, statsFailed, first, onOpen }: { c: NearbyCourse; s?: NearbyCourseStat; statsFailed: boolean; first: boolean; onOpen: () => void }) {
  const { t } = useTranslation();
  const meta = metaLine(c, s, statsFailed, t as unknown as Tr);
  return (
    <button type="button" data-nearby-row={c.id} onClick={onOpen}
      style={{ display: 'flex', alignItems: 'center', gap: 12, width: '100%', padding: '11px 0', background: 'transparent', border: 0,
        borderTop: first ? 'none' : `1px solid ${T.hair}`, textAlign: 'left', cursor: 'pointer', color: T.ink }}>
      <span style={{ position: 'relative', width: 40, height: 40, borderRadius: 12, overflow: 'hidden', flex: 'none' }}>
        {c.thumbnail
          ? <img src={c.thumbnail} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover', display: 'block' }} />
          : <CourseImageFallback />}
      </span>
      <span style={{ flex: 1, minWidth: 0 }}>
        <span data-nearby-name style={c.isTop100
          ? { display: 'block', fontSize: 14.5, fontWeight: 600, color: T.ink, lineHeight: 1.3 }
          : { display: 'block', fontSize: 14.5, fontWeight: 600, color: T.ink, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
          {shortCourseName(c.name)}
          {c.isTop100 && (
            <span data-nearby-top100 style={{ display: 'inline-block', marginLeft: 6, padding: '1px 6px', borderRadius: 999, border: `1px solid ${T.chip}`,
              fontSize: 9.5, fontWeight: 800, letterSpacing: '0.1em', textTransform: 'uppercase', color: T.ink, verticalAlign: 'middle' }}>
              {t('business.nearby.top100', { defaultValue: 'Top 100' })}
            </span>
          )}
        </span>
        <span data-nearby-meta style={{ display: 'block', marginTop: 2, fontSize: 12.5, color: T.mute, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', ...TAB }}>
          {meta.line}
        </span>
      </span>
      {c.reviewCount >= 1 && c.ratingAvg != null && (
        <span data-nearby-rating style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 3, flex: 'none' }}>
          <span data-nearby-rating-value style={{ fontSize: 15, fontWeight: 700, color: T.ink, ...TAB }}>{c.ratingAvg.toFixed(1)}</span>
          <span style={{ fontSize: 9.5, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase', color: T.dim }}>
            {t('business.nearby.rating', { defaultValue: 'Rating' })}
          </span>
        </span>
      )}
    </button>
  );
}

export interface BusinessNearbyInput { name: string; category?: string | null; lat?: number | null; lng?: number | null }

export function BusinessNearbyCourses({ isClub, viewerId, business }: { isClub: boolean; viewerId?: string; business: BusinessNearbyInput }) {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [sheet, setSheet] = useState(false);
  const eligible = !isClub && NEARBY_CATEGORIES.has(business.category ?? '') && business.lat != null && business.lng != null;
  const nearby = useBusinessNearbyCounts(isClub ? null : business.category, business.lat, business.lng);
  const courses = nearby.data?.courses ?? [];
  const stats = useNearbyCourseStats(viewerId, courses, eligible);

  if (!eligible || nearby.isLoading || nearby.isError || !nearby.data?.courses || courses.length === 0) return null;
  if (viewerId && stats.isLoading) return null;
  // CB115 tidy: no signed-in viewer means the stats read never runs → unavailable, not "No rounds yet".
  const failed = stats.isError || !viewerId;
  const byId = new Map((stats.data ?? []).map((s) => [s.id, s]));
  const shown = courses.slice(0, 4);
  const N = nearby.data.coursesNear ?? courses.length;
  const plays = failed ? null : shown.map((c) => metaLine(c, byId.get(c.id), false).plays).find((p) => p != null) ?? null;
  const open = (id: string) => { setSheet(false); navigate(`/courses/${id}`); };

  return (
    <section data-business-nearby style={{ background: T.card, border: `1px solid ${T.hair}`, borderRadius: 18, padding: 16, margin: '14px 16px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: 12, marginBottom: 10 }}>
        <span style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase', color: T.mute }}>
          {t('business.nearby.kicker', { defaultValue: 'Courses nearby' })}
        </span>
        <span style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: '0.12em', textTransform: 'uppercase', color: T.dim }}>
          {t('business.nearby.within', { defaultValue: 'Within 10 miles' })}
        </span>
      </div>
      {shown.map((c, i) => <Row key={c.id} c={c} s={byId.get(c.id)} statsFailed={failed} first={i === 0} onOpen={() => open(c.id)} />)}
      {plays && (
        <p data-nearby-foot style={{ margin: '6px 0 0', fontSize: 12, lineHeight: 1.45, color: T.dim }}>
          {t('business.nearby.foot', { plays, defaultValue: "{{plays}} is how a course plays: the average score against par in members' rounds." })}
        </p>
      )}
      {courses.length > 4 && (
        <button type="button" data-nearby-all={N} onClick={() => setSheet(true)}
          style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%', marginTop: 12, paddingTop: 12,
            background: 'transparent', border: 0, borderTop: `1px solid ${T.hair}`, cursor: 'pointer', textAlign: 'left' }}>
          <span style={{ fontSize: 14, fontWeight: 600, color: T.ink }}>
            {t('business.nearby.all', { n: formatNumber(N), defaultValue: 'All {{n}} courses near here' })}
          </span>
          <span style={{ color: T.dim }}>›</span>
        </button>
      )}
      <BottomSheet open={sheet} onClose={() => setSheet(false)} ariaLabelledBy="biz-nearby-sheet-title">
        <div data-nearby-sheet style={{ padding: '0 16px 26px' }}>
          <div id="biz-nearby-sheet-title" style={{ fontSize: 17, fontWeight: 700, letterSpacing: '-0.01em', color: T.ink, marginBottom: 10 }}>
            {t('business.nearby.sheetTitle', { name: business.name, defaultValue: 'Courses near {{name}}' })}
          </div>
          <div style={{ borderTop: `1px solid ${T.hair}` }}>
            {courses.map((c, i) => <Row key={c.id} c={c} s={byId.get(c.id)} statsFailed={failed} first={i === 0} onOpen={() => open(c.id)} />)}
          </div>
        </div>
      </BottomSheet>
    </section>
  );
}

/** Hero "Courses near"/"Top 100 near" → card top just below the top chrome. */
export function scrollToNearbyCard() {
  const el = document.querySelector<HTMLElement>('[data-business-nearby]');
  if (!el) return;
  const probe = document.createElement('div');
  probe.style.cssText = 'position:fixed;top:0;height:0;padding-top:max(env(safe-area-inset-top, 0px), 47px);visibility:hidden';
  document.body.appendChild(probe);
  const offset = probe.getBoundingClientRect().height || parseFloat(getComputedStyle(probe).paddingTop) || 47;
  probe.remove();
  scrollElementIntoView(el, { offset, behavior: 'smooth' });
}

