.be4-sheet button:focus-visible{outline:2px solid var(--ep-ink);outline-offset:2px}

/* BE3 opt-in field layout; the shared neutral precision note uses fallback
   tokens for non-editor consumers without changing their field geometry. */
.be3-groups{padding:0 16px}
.be3-groups .ep-row{height:auto;min-height:52px;border-radius:0;box-shadow:none;justify-content:flex-start;padding:13px 0;transition:none}
.be3-groups .ph{color:var(--ep-dim)}
.be3-lock{font-size:13px;color:var(--ep-dim)}
.be3-sheet .be3-fld{display:block;background:var(--ep-inset);border:1px solid var(--ep-hair);border-radius:14px;padding:10px 14px;margin-top:10px;min-width:0}
.be3-fld>span,.be3-field-label{display:block;font-size:10px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:var(--ep-dim)}
.be3-fld input,.be3-fld .be3-country>button,.be3-phone-code>button{display:flex;width:100%;height:auto;min-height:0;padding:0!important;margin-top:4px;border:0!important;box-shadow:none!important;outline:none;background:none!important;color:var(--ep-ink);caret-color:var(--ep-ink);font-size:15.5px;font-weight:500;border-radius:0!important}
.be3-fld .be3-country>button span.text-\[15px\]{font-size:15.5px}
.be3-phone-code{flex:none;width:112px}
.be3-phone-number{flex:1;min-width:0}
.be3-phone-code svg.lucide-chevron-down{display:none}
.be3-sheet .be3-phone-code>button{min-width:0!important;gap:8px}
.be3-sheet .be3-phone-code>button>span{font-size:15.5px}
.be3-sheet .be3-phone-code [data-flag] {flex:none}
.be3-map{border-radius:14px;overflow:hidden;margin-top:14px}
.be3-mapfoot{display:flex;justify-content:space-between;align-items:center;gap:12px;font-size:13.5px;color:var(--ep-mute);margin-top:10px}
.be3-sheet .be3-text-button{height:auto;min-height:0;padding:0;border:0;border-radius:0;background:none;color:var(--ep-ink);font-size:13.5px;font-weight:600;box-shadow:none;white-space:nowrap}
.be3-helper{font-size:13px;line-height:1.45;color:var(--ep-dim);margin:12px 0 0}
.be3-error{color:var(--be1-danger,var(--destructive));font-size:13px;margin-top:8px}
.business-precision-note{background:var(--ep-inset,#1E1E23);border-radius:14px;padding:12px 14px;margin-top:12px;color:var(--ep-ink,#F8FAFC)}
.business-precision-note h3{font-size:14.5px;font-weight:600;margin:0;line-height:normal}
.business-precision-note p{font-size:13px;color:var(--ep-mute,rgba(248,250,252,.62));line-height:1.45;margin:3px 0 0}
.business-precision-note .business-place-pin{height:auto;min-height:0;padding:0;margin-top:10px;border:0;border-radius:0;background:none;color:inherit;font-size:14px;font-weight:600;box-shadow:none}
.be3-sheet input:focus-visible{outline:none}

src/components/business/hero/ClubProfile:
/**
 * ClubProfileHero (CB103) — the golf-club business profile hero, built from
 * the signed-off club-s1-hero mock. Rendered ONLY when the page's isClub
 * condition holds (club_id and at least one course). CB112: non-club
 * businesses render this same hero through optional props (secondAction,
 * insightsTone, stripCells) whose defaults reproduce the club exactly;
 * personal profiles keep HeroShell.
 *
 * The page owns every action (follow, share, menu, message, navigation) and
 * the permission flags; this component only lays them out.
 */
import React from 'react';
import { useTranslation } from 'react-i18next';
import { Share, MoreHorizontal, Plus, MessageCircle, Pencil, ArrowUpRight } from 'lucide-react';
import { getInitialsFromName, avatarFallbackFill, AVATAR_FALLBACK_INK } from '@/lib/avatarFallback';
import { A } from '@/features/courses/components/holes/analytical/tokens';
import { VerifiedBadge } from '@/components/ui/VerifiedBadge';
import { MASTHEAD_KICKER } from '@/components/courses/CourseMasthead';
import { PhotoBandFade } from '@/features/tourhub/components/overview-v3/HybridHeroBands/photoBandMaterial';
import { FallbackCover } from '@/components/profile/hero/FallbackCover';
import { HERO_CONTENT_TOP, HERO_CONTENT_BOTTOM } from '@/lib/heroHeights';

const CANVAS = '#0B0B0D';
const INK = '#F8FAFC';
const MUTE = 'rgba(248,250,252,0.62)';
const DIM = 'rgba(248,250,252,0.42)';
const HAIR = 'rgba(255,255,255,0.08)';
const GLASS_BG = 'rgba(255,255,255,0.07)';
const GLASS_BORDER = '1px solid rgba(255,255,255,0.14)';
const ICON = { size: 16, strokeWidth: 1.9 } as const;
const FIGS: React.CSSProperties = { fontVariantNumeric: 'tabular-nums', fontFeatureSettings: '"kern" 1, "liga" 1' };

export interface ClubPlaceInput {
  city?: string | null;
  region?: string | null;
  country?: string | null;
  firstCourseRegion?: string | null;
  courseCount: number;
}

/** The place value the hero line shows: city/region with nation names
 * filtered out, else the first course's region, else the country. Pure, so
 * shared consumers (CB107.2 Visiting directions) cannot drift from the hero. */
export function clubPlace(
  { city, region, country, firstCourseRegion }: Omit<ClubPlaceInput, 'courseCount'>,
): string {
  const nations = new Set(['england', 'scotland', 'wales', 'northern ireland', 'ireland', 'republic of ireland', 'united kingdom', 'uk', 'great britain', 'britain', 'britain & ireland', country?.trim().toLowerCase()]);
  const own = [city, region].map((s) => s?.trim()).filter((s) => s && !nations.has(s.toLowerCase())).join(', ');
  return own || firstCourseRegion?.trim() || country?.trim() || '';
}

/** "Golf club · Bromley, Kent · 2 courses". Pure, so it is tested directly. */
export function clubPlaceLine(
  { city, region, country, firstCourseRegion, courseCount }: ClubPlaceInput,
  labels: { golfClub: string; courses: (n: number) => string },
): string {
  return [labels.golfClub, clubPlace({ city, region, country, firstCourseRegion }), courseCount >= 2 ? labels.courses(courseCount) : '']
    .filter(Boolean)
    .join(' \u00B7 ');
}

/**
 * CB103 team-row gates — each reuses the permission the app already applies:
 * Your courses = mayHaveClubAnalytics (BusinessCommandCard.showClubAnalytics),
 * Insights = canViewInsights, Post = role !== 'analyst' (BusinessHomeHeader
 * canPost), Edit = canManage or editor (the profile's edit menu item).
 */
export function clubTeamGates(
  membership: { role: string; canViewInsights: boolean; canManage: boolean } | null | undefined,
  clubAnalytics: boolean,
) {
  if (!membership) return null;
  return {
    yourCourses: clubAnalytics,
    insights: membership.canViewInsights,
    post: membership.role !== 'analyst',
    edit: membership.canManage || membership.role === 'editor',
  };
}

export interface ClubTeamActions {
  onYourCourses?: () => void;
  onInsights?: () => void;
  onPost?: () => void;
  onEdit?: () => void;
}

interface Props {
  name: string;
  /** HB6 page-owned heading observation; standalone hero consumers stay inert. */
  nameRef?: React.Ref<HTMLHeadingElement>;
  logoUrl?: string | null;
  coverUrl?: string | null;
  fallbackKey?: string | null;
  verified?: boolean;
  evidenceLine?: string | null;
  placeLine: string;
  onAvatarTap?: () => void;
  onShare: () => void;
  /** The existing menu, rendered around the More circle by the page. */
  renderMore: (trigger: React.ReactElement) => React.ReactNode;
  /** Team row actions; each present only when its permission passes. */
  team: ClubTeamActions | null;
  isFollowing: boolean;
  onFollowToggle: () => void;
  onBookTeeTime: () => void;
  onMessage: () => void;
  messageDisabled?: boolean;
  avgRating?: number | null;
  ratingsCount?: number | null;
  roundsTracked?: number | null;
  membersHere?: number | null;
  onRatingTap?: () => void;
  onRoundsTap?: () => void;
  about?: string | null;
  /** CB112 — replaces the tee-time pill. Omitted = club tee-time; null = no pill. */
  secondAction?: { label: string; arrow?: boolean; soon?: boolean; onTap: () => void } | null;
  /** CB112 — Insights pill tone in the team row; clubs keep glass. */
  insightsTone?: 'white' | 'glass';
  /** CB112 — overrides the club's rating/rounds/members cells. */
  stripCells?: Array<{ key: string; value: string; label: string; color?: string; onTap?: () => void }>;
}

const pill = (kind: 'white' | 'glass'): React.CSSProperties => ({
  display: 'inline-flex', alignItems: 'center', gap: 7, height: 38, padding: '0 16px',
  borderRadius: 999, fontSize: 14.5, fontWeight: 600, whiteSpace: 'nowrap', flex: 'none',
  fontFamily: 'inherit', cursor: 'pointer',
  ...(kind === 'white'
    ? { background: INK, color: CANVAS, border: 'none' }
    : { background: GLASS_BG, border: GLASS_BORDER, color: INK }),
});
const circle = (d: number): React.CSSProperties => ({
  width: d, height: d, borderRadius: 999, flex: 'none', padding: 0,
  background: GLASS_BG, border: GLASS_BORDER, color: INK,
  display: 'inline-flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer',
});

export const ClubProfileHero: React.FC<Props> = (p) => {
  const { t } = useTranslation();
  const initials = getInitialsFromName(p.name) || 'B';
  const showEvidence = !!p.verified && !!p.evidenceLine;
  const team = p.team && Object.values(p.team).some(Boolean) ? p.team : null;

  const cells: Array<{ key: string; value: string; label: string; color?: string; onTap?: () => void }> = p.stripCells ? [...p.stripCells] : [];
  if (!p.stripCells && p.avgRating != null && p.avgRating >= 1 && (p.ratingsCount ?? 0) >= 1) {
    cells.push({
      key: 'rating', value: p.avgRating.toFixed(1),
      label: t('business.clubHero.reviews', { count: p.ratingsCount!, defaultValue: '{{count}} reviews' }),
      color: A.INK, onTap: p.onRatingTap,
    });
  }
  if (!p.stripCells && (p.roundsTracked ?? 0) >= 1) {
    cells.push({ key: 'rounds', value: p.roundsTracked!.toLocaleString(), label: t('business.clubHero.roundsTracked', 'Rounds tracked'), onTap: p.onRoundsTap });
  }
  if (!p.stripCells && (p.membersHere ?? 0) >= 1) {
    cells.push({ key: 'members', value: p.membersHere!.toLocaleString(), label: t('business.clubHero.membersHere', 'Members here') });
  }

  /* FIGURE PLACEMENT: beside the buttons only when the visitor row is Follow
     (or Following) plus Message — a second pill (club tee-time, coach lesson,
     booking) or the team row puts the figures underneath. No dividers in
     either placement. */
  const beside = !team && p.secondAction === null && cells.length > 0 && cells.length <= 2;
  const renderStrip = (placement: 'beside' | 'below') => (
    <div
      data-club-strip=""
      data-strip-placement={placement}
      style={placement === 'beside'
        ? { marginLeft: 'auto', display: 'flex', gap: 14, alignItems: 'center', flex: 'none' }
        : { display: 'flex', gap: 28, justifyContent: 'flex-start', margin: '16px 20px 0', padding: 0 }}
    >
      {cells.map((c) => {
        const body = (
          <>
            <span
              data-cell-value=""
              style={{
                display: 'block',
                fontSize: placement === 'beside' ? 19 : 22,
                fontWeight: 700,
                ...(placement === 'beside' ? { lineHeight: 1 } : { letterSpacing: '-0.01em' }),
                color: c.color ?? INK,
                ...FIGS,
              }}
            >
              {c.value}
            </span>
            <span style={{ display: 'block', marginTop: 4, fontSize: placement === 'beside' ? 9.5 : 10, fontWeight: 800, letterSpacing: '0.12em', textTransform: 'uppercase', color: DIM }}>{c.label}</span>
          </>
        );
        const style: React.CSSProperties = placement === 'beside'
          ? { textAlign: 'center', background: 'none', border: 0, padding: 0, minHeight: 38, display: 'flex', flexDirection: 'column', justifyContent: 'center', color: INK, fontFamily: 'inherit' }
          : { textAlign: 'left', background: 'none', border: 0, padding: 0, color: INK, fontFamily: 'inherit' };
        return c.onTap ? (
          <button key={c.key} type="button" data-cell={c.key} style={style} onClick={c.onTap}>{body}</button>
        ) : (
          <div key={c.key} data-cell={c.key} style={style}>{body}</div>
        );
      })}
    </div>
  );

  const aboutRef = React.useRef<HTMLParagraphElement>(null);
  const [expanded, setExpanded] = React.useState(false);
  const [clamped, setClamped] = React.useState(false);
  React.useEffect(() => {
    const check = () => { const el = aboutRef.current; if (el) setClamped(el.scrollHeight > el.clientHeight); };
    check();
    window.addEventListener('resize', check);
    return () => window.removeEventListener('resize', check);
  }, [p.about]);

  return (
    <section data-club-hero="" style={{ background: CANVAS, fontFamily: 'inherit', color: INK }}>
      <div
        data-club-cover=""
        style={{
          position: 'relative',
          paddingTop: HERO_CONTENT_TOP,
          paddingBottom: HERO_CONTENT_BOTTOM,
          background: CANVAS,
          overflow: 'hidden',
        }}
      >
        {p.coverUrl ? (
          <img src={p.coverUrl} alt="" style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover' }} />
        ) : (
          <FallbackCover />
        )}
        <PhotoBandFade canvas={CANVAS} />

        {/* Identity on the photo: place kicker + Share/More, then crest + name. */}
        <div style={{ position: 'relative', margin: '0 20px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 12, height: 11 * 1.2 }}>
            {p.placeLine ? <span data-club-place="" style={{ ...MASTHEAD_KICKER, minWidth: 0 }}>{p.placeLine}</span> : <span />}
            <div style={{ display: 'flex', gap: 8, flex: 'none', margin: '-11px 0' }}>
              <button type="button" aria-label={t('business.clubHero.share', 'Share')} onClick={p.onShare} style={circle(34)}>
                <Share {...ICON} />
              </button>
              {p.renderMore(
                <button type="button" aria-label={t('business.clubHero.more', 'More options')} style={circle(34)}>
                  <MoreHorizontal {...ICON} />
                </button>,
              )}
            </div>
          </div>

          <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginTop: 8 }}>
            <button
              type="button"
              aria-label={p.name}
              onClick={p.onAvatarTap}
              data-club-crest=""
              style={{ width: 64, height: 64, borderRadius: 16, background: p.logoUrl ? '#F4F4F2' : undefined, overflow: 'hidden', padding: 0, border: 'none', flex: 'none' }}
            >
              {p.logoUrl ? (
                <img src={p.logoUrl} alt={p.name} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
              ) : (
                <span style={{ width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', background: avatarFallbackFill(p.fallbackKey || p.name), color: AVATAR_FALLBACK_INK, fontSize: 20, fontWeight: 600, boxShadow: 'inset 0 0 0 1px rgba(248,250,252,0.10)' }}>
                  {initials}
                </span>
              )}
            </button>
            <div style={{ flex: 1, minWidth: 0 }}>
              <h1 ref={p.nameRef} style={{ margin: 0, fontSize: 26, fontWeight: 800, letterSpacing: 0, lineHeight: 1.1, color: INK, display: '-webkit-box', WebkitBoxOrient: 'vertical', WebkitLineClamp: 2, overflow: 'hidden' }}>
                {p.name}
                {p.verified && (
                  <span aria-label="Verified" style={{ display: 'inline', marginLeft: 7, verticalAlign: -1 }}>
                    <VerifiedBadge size="lg" className="inline" />
                  </span>
                )}
              </h1>
              {showEvidence && (
                <div style={{ marginTop: 4, fontSize: 12.5, fontWeight: 600, lineHeight: 1.4, color: A.AMBER, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                  {p.evidenceLine}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      <div style={{ position: 'relative' }}>
        <div
          data-club-actions={team ? 'team' : 'visitor'}
          className="scrollbar-hide"
          style={{ display: 'flex', gap: 8, padding: '14px 20px 0', overflowX: 'auto', flexWrap: 'nowrap', scrollbarWidth: 'none' }}
        >
          {team ? (
            <>
              {team.onYourCourses && <button type="button" style={pill('white')} onClick={team.onYourCourses}>{t('business.clubHero.yourCourses', 'Your courses')}</button>}
              {team.onInsights && <button type="button" data-insights-pill="" style={pill(p.insightsTone ?? 'glass')} onClick={team.onInsights}>{t('business.clubHero.insights', 'Insights')}</button>}
              {team.onPost && <button type="button" aria-label={t('business.clubHero.post', 'Post as the business')} style={circle(38)} onClick={team.onPost}><Plus {...ICON} /></button>}
              {team.onEdit && <button type="button" aria-label={t('business.clubHero.edit', 'Edit business profile')} style={circle(38)} onClick={team.onEdit}><Pencil {...ICON} /></button>}
            </>
          ) : (
            <>
              {p.isFollowing ? (
                <button type="button" style={pill('glass')} onClick={p.onFollowToggle}>{t('business.clubHero.following', 'Following')}</button>
              ) : (
                <button type="button" style={pill('white')} onClick={p.onFollowToggle}>
                  <Plus size={15} strokeWidth={1.9} />
                  {t('business.clubHero.follow', 'Follow')}
                </button>
              )}
              {p.secondAction === undefined ? (
              <button
                type="button"
                data-tee-soon=""
                style={{ ...pill('glass'), color: 'rgba(248,250,252,0.5)', borderColor: HAIR }}
                onClick={p.onBookTeeTime}
              >
                {t('business.clubHero.bookTeeTime', 'Book a tee time')}
                <span data-soon-tag="" style={{ fontSize: 9.5, fontWeight: 800, letterSpacing: '0.1em', textTransform: 'uppercase', color: DIM, border: GLASS_BORDER, borderRadius: 999, padding: '2px 7px' }}>
                  {t('business.clubHero.soon', 'Soon')}
                </span>
              </button>
              ) : p.secondAction ? (
                <button
                  type="button"
                  data-second-pill=""
                  style={p.secondAction.soon ? { ...pill('glass'), color: 'rgba(248,250,252,0.5)', borderColor: HAIR } : pill('glass')}
                  onClick={p.secondAction.onTap}
                >
                  {p.secondAction.label}
                  {p.secondAction.soon && (
                    <span data-soon-tag="" style={{ fontSize: 9.5, fontWeight: 800, letterSpacing: '0.1em', textTransform: 'uppercase', color: DIM, border: GLASS_BORDER, borderRadius: 999, padding: '2px 7px' }}>
                      {t('business.clubHero.soon', 'Soon')}
                    </span>
                  )}
                  {p.secondAction.arrow && <ArrowUpRight data-arrow="" size={14} strokeWidth={1.9} />}
                </button>
              ) : null}
              <button type="button" aria-label={t('business.clubHero.message', 'Message')} style={circle(38)} onClick={p.onMessage} disabled={p.messageDisabled}>
                <MessageCircle {...ICON} />
              </button>
            </>
          )}
          {beside ? renderStrip('beside') : null}
        </div>
      </div>

      {!beside && cells.length > 0 ? renderStrip('below') : null}

      {p.about && (
        <>
          <p
            ref={aboutRef}
            data-club-about=""
            className={expanded ? 'whitespace-pre-wrap' : 'whitespace-pre-wrap line-clamp-3'}
            style={{ padding: '14px 18px 0', fontSize: 14.5, lineHeight: 1.5, color: MUTE, overflowWrap: 'anywhere' }}
          >
            {p.about}
          </p>
          {(clamped || expanded) && (
            <button
              type="button"
              data-club-about-toggle=""
              onClick={() => setExpanded((v) => !v)}
              style={{ padding: '6px 18px 0', minHeight: 36, background: 'none', border: 'none', fontSize: 14, fontWeight: 600, color: INK, display: 'flex', alignItems: 'center', fontFamily: 'inherit' }}
            >
              {expanded ? t('business.clubHero.aboutLess', 'Less') : t('business.clubHero.aboutMore', 'More')}
            </button>
          )}
        </>
      )}
    </section>
  );
};

export default ClubProfileHero;

src/components/business/home/BusinessDoN:
/**
 * CB68 — Business home Section 3: Do next. Signed-off biz-donext.html.
 *
 * Renders NOTHING until every source its role can see has settled, then
 * once; with no trigger it renders nothing at all (no heading, no space).
 * A source that errors drops only its own trigger (see doNext.ts). Sources:
 * the membership row (already settled by the page), pending team requests,
 * the unreplied-reviews summary count and useBusinessWeek (shared cache with This week).
 * CB68.1: review_date is the golfer's played date, so no wait is claimed and the
 * read fetches zero rows (summary only). Copy: common:business.doNext.*.
 */
import { useMemo } from 'react';
import { useTranslation } from 'react-i18next';
import { useNavigate } from 'react-router-dom';
import type { BusinessMembership } from '@/hooks/useMyBusinesses';
import { useBusinessPendingRequestsOldest } from '@/hooks/useBusinessPendingRequestsOldest';
import { useBusinessReviews } from '@/hooks/useBusinessReviews';
import { useBusinessWeek } from '@/hooks/useBusinessWeek';
import { usePostStudioStore } from '@/stores/usePostStudioStore';
import { H } from './BusinessHomeHeader';
import { buildDoNext, resolveDoNextMsg, resolveDoNextSub, type DoNextItem } from './doNext';

/** Only the summary count is needed; no review rows are read. */
export const DO_NEXT_REVIEWS_LIMIT = 0;

export function BusinessDoNextCard({ membership }: { membership: BusinessMembership }) {
  const navigate = useNavigate();
  const { t, i18n } = useTranslation();
  const { role, business } = membership;
  const manager = role === 'owner' || role === 'admin';
  const editorPlus = manager || role === 'editor';
  const needReviews = manager && !!business.club_id && business.is_verified === true;

  const pendingQ = useBusinessPendingRequestsOldest(manager ? business.id : undefined);
  const reviewsQ = useBusinessReviews(needReviews ? business.id : undefined, {
    filter: 'unreplied', sort: 'recent', limit: DO_NEXT_REVIEWS_LIMIT,
  });
  const weekQ = useBusinessWeek(editorPlus ? business.id : undefined);

  const settled =
    (!manager || !pendingQ.isPending) &&
    (!needReviews || !reviewsQ.isPending) &&
    (!editorPlus || !weekQ.isPending);

  const items = useMemo<DoNextItem[]>(() => {
    if (!editorPlus || !settled) return [];
    const reviewsData = reviewsQ.data;
    return buildDoNext({
      role,
      business,
      pending: pendingQ.isError ? undefined : pendingQ.data,
      reviews: reviewsQ.isError || !reviewsData ? undefined : { awaiting: reviewsData.summary.awaiting_reply },
      week: weekQ.isError ? undefined : weekQ.data,
      locale: i18n?.language,
    });
  }, [editorPlus, settled, role, business, pendingQ.isError, pendingQ.data, reviewsQ.isError, reviewsQ.data, weekQ.isError, weekQ.data, i18n?.language]);

  if (items.length === 0) return null;

  const tap = (item: DoNextItem) => {
    if (item.onTap.type === 'post') {
      usePostStudioStore.getState().openPostStudio({ actorType: 'business', actorId: item.onTap.actorId });
    } else {
      navigate(item.onTap.to);
    }
  };

  return (
    <section
      data-business-do-next=""
      style={{ margin: '12px 16px 0', background: H.card, border: `1px solid ${H.line}`, borderRadius: 18, padding: 16 }}
    >
      <div style={{ fontSize: 10.5, fontWeight: 800, letterSpacing: '0.16em', textTransform: 'uppercase', color: H.mute }}>
        {t('business.doNext.kicker')}
      </div>
      <div style={{ marginTop: 10 }}>
        {items.map((item, i) => (
          <div
            key={item.kind}
            data-do-next={item.kind}
            style={{
              display: 'flex', gap: 12, alignItems: 'center',
              padding: i === 0 ? '4px 0 11px' : '11px 0',
              borderTop: i === 0 ? 0 : `1px solid ${H.hair}`,
            }}
          >
            <div
              data-do-next-num=""
              style={{
                width: 22, height: 22, borderRadius: 11, border: '1px solid rgba(255,255,255,0.18)', flex: 'none',
                display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 11, fontWeight: 800, color: H.mute,
              }}
            >
              {i + 1}
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <b style={{ display: 'block', fontSize: 14, fontWeight: 700, color: H.ink }}>{resolveDoNextMsg(t, item.title)}</b>
              {item.sub.length > 0 && (
                <span style={{ display: 'block', marginTop: 2, fontSize: 12, lineHeight: 1.38, color: H.mute }}>{resolveDoNextSub(t, item.sub)}</span>
              )}
            </div>
            <button
              type="button"
              data-do-next-action=""
              onClick={() => tap(item)}
              style={{
                flex: 'none', height: 30, padding: '0 13px', borderRadius: 15, border: `1px solid ${H.btnHair}`,
                background: H.actFill, color: H.ink, fontSize: 12.5, fontWeight: 700, display: 'flex', alignItems: 'center',
              }}
            >
              {resolveDoNextMsg(t, item.action)}
            </button>
          </div>
        ))}
      </div>
    </section>
  );
}

src/components/business/home/BusinessHom:
/**
 * CB66 — Business home, section 1: the header (switcher, identity, buttons,
 * status rows). Values are literal from the signed-off biz-header.html.
 *
 * Ownership:
 * - Verification state comes from `deriveVerificationState` plus the domain
 *   rule (requires_domain_check && !domain_confirmed); claim rules mirror
 *   BusinessCommandCard's canClaimCourse. Status rows render only after both
 *   per-business reads settle, so rows may appear but never disappear.
 * - Status rows and the ··· menu are owner/admin only; Delete is owner only.
 * - Share goes through `shareBusinessProfile` (shared with BusinessProfilePage).
 * - Business colour: memberships carry no colour field, so initials sit on a
 *   deterministic gradient picked from the business id.
 */
import { useState } from 'react';
import { getInitialsFromName } from '@/lib/avatarFallback';
import { useNavigate } from 'react-router-dom';
import type { LucideIcon } from 'lucide-react';
import { MoreHorizontal, Plus, Eye, Share, Trash2, ShieldCheck, Globe, Clock, AlertCircle, Flag } from 'lucide-react';
import {
  DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { VerifiedBadge } from '@/components/ui/VerifiedBadge';
import { getCityCountry } from '@/lib/locationDisplay';
import type { BusinessMembership } from '@/hooks/useMyBusinesses';
import { useBusinessVerificationRequest, deriveVerificationState } from '@/hooks/useBusinessVerificationRequest';
import { useBusinessCourseClaim } from '@/hooks/useBusinessCourseClaim';
import { CLUB_ANALYTICS_CATEGORY } from '@/features/business/clubAnalytics/useClubCourseLink';
import { usePostStudioStore } from '@/stores/usePostStudioStore';
import { shareBusinessProfile, businessProfileShareUrl } from '@/lib/business/shareBusinessProfile';
import { ClaimYourCourseSheet } from '@/components/business/ClaimYourCourseSheet';
import { Skeleton } from '@/components/ui/skeleton';

/* Literal mock values. */
export const H = {
  ink: '#F8FAFC',
  mute: 'rgba(248,250,252,0.62)',
  dim: 'rgba(248,250,252,0.42)',
  line: 'rgba(255,255,255,0.08)',
  card: '#17171B',
  onInk: '#0B0B0D',
  btnHair: 'rgba(255,255,255,0.14)',
  actFill: 'rgba(255,255,255,0.04)',
  chipOn: 'rgba(255,255,255,0.9)',
  menuBg: '#202026',
  menuHair: 'rgba(255,255,255,0.1)',
  hair: 'rgba(255,255,255,0.06)',
  danger: '#FF6B6B',
} as const;

const GRADIENTS = [
  'linear-gradient(140deg,#5a3d1f,#a0703c)',
  'linear-gradient(140deg,#2c4a2e,#5f8a4f)',
  'linear-gradient(140deg,#1f3a5a,#3f6e9c)',
  'linear-gradient(140deg,#4a2c4a,#8a4f7f)',
  'linear-gradient(140deg,#4a3a1f,#8a7a3c)',
];
export function businessColour(id: string): string {
  let h = 0;
  for (let i = 0; i < id.length; i++) h = (h * 31 + id.charCodeAt(i)) >>> 0;
  return GRADIENTS[h % GRADIENTS.length];
}
export function businessInitials(name: string): string {
  return getInitialsFromName(name);
}
/**
 * CB66.1: drop trailing words (and trailing punctuation-only words like "&")
 * while the name is over 14 characters; never cut inside a word, never an
 * ellipsis. Returns null when even the first word alone is over 14, so the
 * button falls back to a bare "Post".
 */
export function shortBusinessName(name: string): string | null {
  const words = name.trim().split(/\s+/);
  const punctOnly = (w: string) => !/[\p{L}\p{N}]/u.test(w);
  while (words.length > 1 && words.join(' ').length > 14) {
    words.pop();
    while (words.length > 1 && punctOnly(words[words.length - 1])) words.pop();
  }
  const result = words.join(' ');
  return result.length <= 14 ? result : null;
}

export const ROLE_LINE: Record<BusinessMembership['role'], string> = {
  owner: "You're the owner",
  admin: "You're an admin",
  editor: "You're an editor",
  analyst: "You're an analyst",
};

type Biz = BusinessMembership['business'];

function Logo({ business, size, radius, fontSize }: { business: Biz; size: number; radius: number; fontSize: number }) {
  return (
    <div
      data-business-logo=""
      className="shrink-0 overflow-hidden flex items-center justify-center"
      style={{
        width: size, height: size, borderRadius: radius,
        background: business.logo_url ? '#1a1a1f' : businessColour(business.id),
        border: size >= 60 ? `1px solid ${H.line}` : undefined,
        fontSize, fontWeight: 800, color: '#fff',
      }}
    >
      {business.logo_url
        ? <img src={business.logo_url} alt="" className="w-full h-full object-cover" />
        : businessInitials(business.name)}
    </div>
  );
}

/* ─────────────────────── switcher ─────────────────────── */

export function BusinessSwitcher({
  memberships, selectedId, onSelect, onAdd,
}: { memberships: BusinessMembership[]; selectedId: string | null; onSelect: (id: string) => void; onAdd: () => void }) {
  return (
    <div
      data-switcher=""
      className="flex no-scrollbar"
      style={{ gap: 8, padding: '10px 16px 4px', overflowX: 'auto', flexWrap: 'nowrap' }}
    >
      {memberships.map((m) => {
        const on = m.business.id === selectedId;
        return (
          <button
            key={m.business.id}
            type="button"
            data-chip={m.business.id}
            aria-pressed={on}
            onClick={() => onSelect(m.business.id)}
            className="flex items-center shrink-0"
            style={{
              gap: 7, height: 36, padding: '0 12px 0 5px', borderRadius: 18,
              border: `1px solid ${on ? H.chipOn : H.line}`, background: 'transparent',
              color: on ? H.ink : H.mute, fontSize: 13, fontWeight: 600, whiteSpace: 'nowrap',
            }}
          >
            <Logo business={m.business} size={26} radius={9} fontSize={10} />
            {m.business.name}
          </button>
        );
      })}
      <button
        type="button"
        data-chip-add=""
        onClick={onAdd}
        className="flex items-center shrink-0"
        style={{
          gap: 4, height: 36, padding: '0 12px', borderRadius: 18, border: `1px solid ${H.line}`,
          background: 'transparent', color: H.mute, fontSize: 13, fontWeight: 600, whiteSpace: 'nowrap',
        }}
      >
        <Plus style={{ width: 16, height: 16 }} strokeWidth={1.9} />
        Add
      </button>
    </div>
  );
}

/* ─────────────────────── status row ─────────────────────── */

function StatusRow({
  kind, icon: Icon, title, sub, action, onAction,
}: {
  kind: string;
  icon: LucideIcon;
  title: string; sub: string; action?: string; onAction?: () => void;
}) {
  return (
    <div
      data-status-row={kind}
      className="flex items-center"
      style={{
        margin: '10px 16px 0', border: `1px solid ${H.line}`, background: H.card,
        borderRadius: 14, padding: '11px 12px 11px 14px', gap: 12,
      }}
    >
      <span className="flex shrink-0" style={{ color: H.mute }}><Icon style={{ width: 16, height: 16 }} strokeWidth={1.9} /></span>
      <div className="flex-1 min-w-0">
        <b className="block" style={{ fontSize: 13.5, fontWeight: 700, color: H.ink }}>{title}</b>
        <span className="block" style={{ marginTop: 2, fontSize: 12, lineHeight: 1.35, color: H.mute }}>{sub}</span>
      </div>
      {action && (
        <button
          type="button"
          data-status-action=""
          onClick={onAction}
          className="shrink-0 flex items-center"
          style={{
            height: 30, padding: '0 13px', borderRadius: 15, border: `1px solid ${H.btnHair}`,
            background: H.actFill, color: H.ink, fontSize: 12.5, fontWeight: 700,
          }}
        >
          {action}
        </button>
      )}
    </div>
  );
}

function StatusRows({ business, userId }: { business: Biz; userId: string }) {
  const navigate = useNavigate();
  const [claimOpen, setClaimOpen] = useState(false);
  const { data: request, isLoading: vLoading } = useBusinessVerificationRequest(business.id);
  const { data: claim, isLoading: cLoading } = useBusinessCourseClaim(business.id);
  if (vLoading || cLoading) return null;

  const state = deriveVerificationState(business.is_verified, request);
  const domain = !!request?.requires_domain_check && !request?.domain_confirmed;
  // Today's card and menu send every unverified state to the verification flow.
  const toVerify = () => navigate(`/business/${business.id}/verification`);

  let verification: React.ReactNode = null;
  if (state === 'none') {
    verification = <StatusRow kind="none" icon={ShieldCheck} title="Not verified yet" sub={`The badge tells golfers this is the real ${business.name}.`} action="Get verified" onAction={toVerify} />;
  } else if (state === 'pending' && domain) {
    verification = <StatusRow kind="domain" icon={Globe} title="Verify your domain" sub="The last step before your verification is reviewed." action="Verify" onAction={toVerify} />;
  } else if (state === 'pending') {
    verification = <StatusRow kind="pending" icon={Clock} title="Verification pending" sub="Our team is reviewing your request." />;
  } else if (state === 'needs_more_info') {
    verification = <StatusRow kind="needs_more_info" icon={AlertCircle} title="We need a little more" sub="Your verification request is waiting on you." action="Respond" onAction={toVerify} />;
  } else if (state === 'rejected') {
    verification = <StatusRow kind="rejected" icon={ShieldCheck} title="Verification not approved" sub="You can apply again with new evidence." action="Reapply" onAction={toVerify} />;
  }

  let course: React.ReactNode = null;
  if (business.category === CLUB_ANALYTICS_CATEGORY && !business.club_id) {
    const inFlight = claim?.status === 'pending' || claim?.status === 'needs_more_info';
    course = inFlight
      ? <StatusRow kind="claim_pending" icon={Clock} title={`Your claim on ${claim?.courseName || business.name} is with our team`} sub="Claiming a course is separate from verification." />
      : <StatusRow kind="claim" icon={Flag} title="Claim your course" sub={`Link ${business.name} to its course page to unlock course analytics.`} action="Claim" onAction={() => setClaimOpen(true)} />;
  }

  return (
    <>
      {verification}
      {course}
      <ClaimYourCourseSheet open={claimOpen} onClose={() => setClaimOpen(false)} businessId={business.id} businessName={business.name} userProfileId={userId} />
    </>
  );
}

/* ─────────────────────── header ─────────────────────── */

export function BusinessHomeHeader({
  membership, userId, onRequestDelete,
}: { membership: BusinessMembership; userId: string; onRequestDelete: (input: { id: string; name: string }) => void }) {
  const navigate = useNavigate();
  const [menuOpen, setMenuOpen] = useState(false);
  const { business, role } = membership;
  const canManage = role === 'owner' || role === 'admin';
  const canPost = role !== 'analyst';
  const loc = getCityCountry({ city: business.city, region: business.region, country: business.country, location: business.location });
  // CB72: Other is a placeholder, not part of the business identity.
  const category = business.category?.trim();
  const subline = [category && category !== 'Other' ? category : null, loc].filter(Boolean).join(' · ');
  const slugOrId = business.slug || business.id;

  const btn: React.CSSProperties = {
    flex: 1, height: 44, borderRadius: 14, gap: 7, fontSize: 14, fontWeight: 700,
  };
  const menuItem: React.CSSProperties = { height: 44, padding: '0 14px', gap: 10, fontSize: 14, fontWeight: 600 };

  return (
    <div data-business-header="" data-role={role}>
      <div style={{ padding: '16px 16px 0' }}>
        <div className="flex items-center" style={{ gap: 14 }}>
          <Logo business={business} size={60} radius={18} fontSize={20} />
          <div className="min-w-0 flex-1">
            <div className="flex items-center" style={{ gap: 7, fontSize: 22, fontWeight: 800, letterSpacing: '-0.025em', color: H.ink, lineHeight: 1.2 }}>
              <span className="truncate">{business.name}</span>
              {business.is_verified && <span data-verified-badge="" className="inline-flex shrink-0"><VerifiedBadge size="sm" className="!w-[17px] !h-[17px]" /></span>}
            </div>
            {subline && <div data-subline="" style={{ marginTop: 3, fontSize: 13, color: H.mute }}>{subline}</div>}
            <div data-role-line="" style={{ marginTop: 2, fontSize: 12, color: H.dim }}>{ROLE_LINE[role]}</div>
          </div>
          {canManage && (
            <DropdownMenu open={menuOpen} onOpenChange={setMenuOpen}>
              <DropdownMenuTrigger asChild>
                <button type="button" aria-label="More options" data-header-menu="" className="self-start shrink-0 flex items-center justify-center" style={{ minWidth: 40, minHeight: 40, marginTop: -6, marginRight: -10, color: H.mute, background: 'transparent', border: 'none' }}>
                  <MoreHorizontal style={{ width: 16, height: 16 }} strokeWidth={1.9} />
                </button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="p-0" style={{ width: 250, background: H.menuBg, border: `1px solid ${H.menuHair}`, borderRadius: 14, padding: '4px 0', boxShadow: '0 12px 30px rgba(0,0,0,.5)' }}>
                <DropdownMenuItem
                  data-menu-item="share"
                  className="cursor-pointer rounded-none"
                  style={{ ...menuItem, color: H.ink }}
                  onClick={() => shareBusinessProfile({ businessId: business.id, name: business.name, url: businessProfileShareUrl(slugOrId), userId })}
                >
                  <Share style={{ width: 16, height: 16 }} strokeWidth={1.9} />Share profile
                </DropdownMenuItem>
                {role === 'owner' && (
                  <DropdownMenuItem
                    data-menu-item="delete"
                    className="cursor-pointer rounded-none"
                    style={{ ...menuItem, color: H.danger, borderTop: `1px solid ${H.hair}` }}
                    onClick={() => {
                      // Close the menu before the hoisted dialog opens (Radix layer race).
                      setMenuOpen(false);
                      requestAnimationFrame(() => onRequestDelete({ id: business.id, name: business.name }));
                    }}
                  >
                    <Trash2 style={{ width: 16, height: 16 }} strokeWidth={1.9} />Delete business profile
                  </DropdownMenuItem>
                )}
              </DropdownMenuContent>
            </DropdownMenu>
          )}
        </div>
        <div className="flex" style={{ marginTop: 14, gap: 8 }}>
          {canPost && (
            <button
              type="button"
              data-cta="post"
              onClick={() => usePostStudioStore.getState().openPostStudio({ actorType: 'business', actorId: business.id })}
              className="flex items-center justify-center min-w-0"
              style={{ ...btn, background: H.ink, color: H.onInk, border: 'none' }}
            >
              <Plus className="shrink-0" style={{ width: 16, height: 16 }} strokeWidth={1.9} />
              <span className="truncate">{(() => { const s = shortBusinessName(business.name); return s ? `Post as ${s}` : 'Post'; })()}</span>
            </button>
          )}
          <button
            type="button"
            data-cta="view"
            onClick={() => navigate(`/business/${slugOrId}`)}
            className="flex items-center justify-center"
            style={{ ...btn, background: 'transparent', border: `1px solid ${H.btnHair}`, color: H.ink }}
          >
            <Eye className="shrink-0" style={{ width: 16, height: 16 }} strokeWidth={1.9} />
            View profile
          </button>
        </div>
      </div>
      {canManage && <StatusRows key={business.id} business={business} userId={userId} />}
    </div>
  );
}

/* ─────────────────────── loading ─────────────────────── */

export function BusinessHomeHeaderSkeleton() {
  const sk = { background: 'rgba(255,255,255,0.06)', borderRadius: 8 } as const;
  return (
    <div data-business-header-skeleton="">
      <div className="flex" style={{ gap: 8, padding: '10px 16px 4px' }}>
        <Skeleton style={{ ...sk, width: 110, height: 36, borderRadius: 18 }} />
        <Skeleton style={{ ...sk, width: 70, height: 36, borderRadius: 18 }} />
      </div>
      <div style={{ padding: '16px 16px 0' }}>
        <div className="flex items-center" style={{ gap: 14 }}>
          <Skeleton style={{ ...sk, width: 60, height: 60, borderRadius: 18 }} />
          <div style={{ flex: 1 }}>
            <Skeleton style={{ ...sk, width: '58%', height: 22 }} />
            <Skeleton style={{ ...sk, width: '76%', height: 13, marginTop: 8 }} />
            <Skeleton style={{ ...sk, width: '46%', height: 12, marginTop: 6 }} />
          </div>
        </div>
        <div className="flex" style={{ marginTop: 14 }}>
          <Skeleton style={{ ...sk, flex: 1, height: 44, borderRadius: 14 }} />
        </div>
