          {showTrackingGap(d.gap.joined, d.gap.signup_starts) && (
            <TrackingGap joined={d.gap.joined!} starts={d.gap.signup_starts ?? 0} />
          )}
          {d.funnels.map((f) => <FunnelPanel key={f.key} f={f} />)}
        </>
