/** Health: App lens (health_app.html). */
import React, { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { trackError } from '@/lib/errorTracking';
import { adminTheme as t } from '../../theme';
import { FooterButton, Head, Muted, Panel, PanelError, PanelSkeleton, ROW_RULE, Slot, FIG_LABEL } from '../analytics/analyticsUi';
import { dateLabel, num } from '../analytics/analyticsFormat';
import { useHealthApp, type HealthApp } from '../../hooks/useHealthLenses';
import { usePushHealth } from '../../hooks/usePushHealth';
import { useEchoEngineHealth } from '../../hooks/useEchoEngineHealth';
import { crashFree } from './healthIssues';
import { ageOf, plural } from './healthText';
import { H, META } from './healthUi';

function CrashFree({ a }: { a: HealthApp }) {
  const cf = crashFree(a);
  const color = !cf ? t.ink : cf.pct >= 99 ? H.okText : cf.pct >= 95 ? H.amber : H.dangerText;
  let body: string;
  if (!cf) body = 'Waiting for sessions that report their build.';
  else if ((a.errors_7d_current ?? 0) > 0) body = `${plural(a.errors_7d_current!, 'error')} from the current build this week, the last ${ageOf(a.last_current_error_at)} ago.`;
  else if ((a.errors_14d ?? 0) === 0) body = 'No errors in 14 days.';
  else if ((a.errors_14d_old ?? 0) > 0) body = `No errors from the current build. The ${plural(a.errors_14d_old!, 'error')} in the last 14 days all came from ${plural(a.old_error_members ?? 0, 'member')} on old builds.`;
  else body = 'No errors from the current build.';
  return (
    <Panel style={{ padding: 16 }}>
      <Head title="Crash-free sessions" side={<>current build &middot; 7 days</>} />
      <div style={{ marginTop: 8, display: 'flex', alignItems: 'baseline', gap: 10 }}>
        <span style={{ fontSize: 44, fontWeight: 800, letterSpacing: '-0.03em', lineHeight: 1, color }}>{cf ? cf.text : '-'}</span>
        {cf && <span style={{ fontSize: 12.5, fontWeight: 600, color: t.inkMuted }}>of {plural(a.sessions_7d_current!, 'session')}</span>}
      </div>
      <div style={{ marginTop: 8, fontSize: 12.5, lineHeight: 1.45, color: t.inkMuted }}>{body}</div>
    </Panel>
  );
}

function Builds({ a }: { a: HealthApp }) {
  const [all, setAll] = useState(false);
  const b = a.builds;
  const tot = b.tracked_sessions ?? 0;
  const pctOf = (v: number | null) => (tot ? Math.min(100, (100 * (v ?? 0)) / tot) : 0);
  const legend = (c: string, label: string, sub: string) => (
    <span>
      <span style={{ display: 'inline-block', width: 8, height: 8, borderRadius: 2, background: c, marginRight: 6 }} />{label}
      <span style={{ display: 'block', marginTop: 2, fontSize: 10, color: t.inkFaint }}>{sub}</span>
    </span>
  );
  const members = all ? a.old_members : a.old_members.slice(0, 3);
  return (
    <Panel style={{ paddingBottom: a.old_members.length > 3 ? 4 : undefined }}>
      <Head title="Builds in use" side={<>sessions &middot; 7 days</>} />
      {tot === 0 ? (
        <>
          <div style={{ marginTop: 8, fontSize: 28, fontWeight: 800, lineHeight: 1 }}>-</div>
          <Muted style={{ marginTop: 8 }}>No sessions have reported a build yet.</Muted>
        </>
      ) : (
        <>
          <div style={{ marginTop: 8, display: 'flex', alignItems: 'baseline', gap: 8 }}>
            <span style={{ fontSize: 28, fontWeight: 800, letterSpacing: '-0.02em', lineHeight: 1 }}>{Math.round(pctOf(b.current))}%</span>
            <span style={{ fontSize: 12.5, fontWeight: 600, color: t.inkMuted }}>on the current build</span>
          </div>
          <div style={{ marginTop: 12, display: 'flex', height: 14, borderRadius: 4, overflow: 'hidden', gap: 2 }}>
            <div style={{ width: `${pctOf(b.current)}%`, background: H.okBar }} />
            <div style={{ width: `${pctOf(b.previous)}%`, background: H.inkSoft }} />
            {(b.older ?? 0) > 0 && <div style={{ flex: 1, background: H.amber }} />}
          </div>
          <div style={{ marginTop: 10, display: 'grid', gridTemplateColumns: 'repeat(3, minmax(0, 1fr))', gap: 6, fontSize: 11 }}>
            {legend(H.okBar, 'Current', `${(a.build_id ?? '-').slice(0, 7)} · ${dateLabel(b.current_first_seen)}`)}
            {legend(H.inkSoft, 'Previous', 'one behind')}
            {legend(H.amber, 'Older', b.older_builds == null ? '-' : plural(b.older_builds, 'build'))}
          </div>
        </>
      )}
      <div style={{ marginTop: 14, ...FIG_LABEL }}>Members on old builds</div>
      <div style={{ marginTop: 4 }}>
        {!a.old_members.length && <Muted style={{ padding: '9px 0', borderTop: ROW_RULE }}>Everyone is on the current build.</Muted>}
        {members.map((m) => (
          <Link key={m.user_id} to={`/admin-v2/users?member=${m.user_id}`} style={{
            display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) auto', columnGap: 10, alignItems: 'center', padding: '9px 0', borderTop: ROW_RULE, color: t.ink, textDecoration: 'none',
          }}>
            <span style={{ minWidth: 0 }}>
              <span style={{ display: 'block', fontSize: 13, fontWeight: 700 }}>{m.name ?? '-'}</span>
              <span style={META}>build {(m.build ?? '-').slice(0, 7)} &middot; last seen {ageOf(m.last_seen)} ago</span>
            </span>
            {(m.errors ?? 0) > 0 && <span style={{ fontSize: 12, fontWeight: 800, color: H.amber }}>{plural(m.errors!, 'error')}</span>}
          </Link>
        ))}
      </div>
      {a.old_members.length > 3 && !all && (
        <div style={{ margin: '0 -16px' }}><FooterButton onClick={() => setAll(true)}>{a.old_members.length - 3} more</FooterButton></div>
      )}
    </Panel>
  );
}

function Errors({ a }: { a: HealthApp }) {
  const days = a.daily.slice(-14);
  const max = Math.max(0, ...days.map((d) => (d.current ?? 0) + (d.old ?? 0)));
  const h = (v: number | null) => (max > 0 ? Math.min(100, (100 * (v ?? 0)) / max) : 0);
  return (
    <Panel>
      <Head title="Errors" side="14 days" />
      {(a.errors_14d ?? 0) === 0 && !a.top.length ? (
        <Muted style={{ marginTop: 10 }}>No errors in 14 days.</Muted>
      ) : (
        <>
          <div style={{ marginTop: 14, height: 64, display: 'grid', gridTemplateColumns: 'repeat(14, minmax(0, 1fr))', gap: 4, alignItems: 'end' }}>
            {days.map((d) => (
              <div key={d.d} style={{ display: 'flex', flexDirection: 'column', justifyContent: 'flex-end', height: '100%', gap: 1 }}>
                <div style={{ borderRadius: 2, height: `${h(d.old)}%`, background: H.inkOld }} />
                {(d.current ?? 0) > 0
                  ? <div style={{ borderRadius: 2, height: `${h(d.current)}%`, background: H.dangerBar }} />
                  : <div style={{ borderRadius: 2, height: 2, background: H.track }} />}
              </div>
            ))}
          </div>
          <div style={{ marginTop: 4, display: 'flex', justifyContent: 'space-between', fontSize: 9.5, fontWeight: 700, color: t.inkFaint }}>
            <span>{dateLabel(days[0]?.d)}</span><span>today</span>
          </div>
          <div style={{ marginTop: 10, display: 'flex', gap: 14, fontSize: 10.5, color: t.inkFaint }}>
            {([['current build', H.dangerBar], ['old builds', H.inkOld]] as const).map(([l, c]) => (
              <span key={l} style={{ display: 'inline-flex', alignItems: 'center', gap: 5 }}><span style={{ width: 8, height: 8, borderRadius: 2, background: c }} />{l}</span>
            ))}
          </div>
          <div style={{ marginTop: 14, ...FIG_LABEL }}>Most frequent</div>
          {!a.top.length && <Muted style={{ padding: '9px 0' }}>No errors in 14 days.</Muted>}
          {a.top.map((e, i) => (
            <div key={i} style={{ display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) auto', columnGap: 10, alignItems: 'center', padding: '9px 0', borderTop: ROW_RULE }}>
              <span style={{ minWidth: 0 }}>
                <span style={{ display: 'block', fontSize: 12.5, fontWeight: 700, fontFamily: H.mono, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{e.message}</span>
                <span style={META}>{e.on_current ? 'current build' : 'old builds only'} &middot; {e.members == null ? '-' : plural(e.members, 'member')} &middot; last {ageOf(e.last_at)} ago</span>
              </span>
              <span style={{ fontSize: 12, fontWeight: 800 }}>{num(e.n)}</span>
            </div>
          ))}
        </>
      )}
    </Panel>
  );
}

function Services() {
  const push = usePushHealth();
  const echo = useEchoEngineHealth();
  if (push.isLoading || echo.isLoading) return <PanelSkeleton height={150} />;
  if (!push.data && !echo.data) return <PanelError onRetry={() => { void push.refetch(); void echo.refetch(); }} />;
  const q = push.data?.queue;
  const latest = echo.data?.latest ?? [];
  const okN = latest.filter((x) => x.ok).length;
  const newest = latest.reduce<string | null>((m, x) => (!m || x.checked_at > m ? x.checked_at : m), null);
  return (
    <Panel>
      <Head title="Services" />
      <div style={{ marginTop: 10, display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) auto', columnGap: 10, alignItems: 'center', paddingBottom: 12 }}>
        <span>
          <span style={{ display: 'block', fontSize: 13.5, fontWeight: 700 }}>Push notifications</span>
          <span style={META}>
            {q ? <>{num(q.sent_24h)} sent in 24h &middot; median delivery {q.latency_p50_ms == null ? '-' : `${Math.round(q.latency_p50_ms)}ms`} &middot; {num(q.pending_now)} waiting</> : '-'}
          </span>
        </span>
        <span style={{ fontSize: 13, fontWeight: 800, color: !q ? t.ink : q.errored_24h > 0 ? H.dangerText : H.okText }}>{q ? `${num(q.errored_24h)} failed` : '-'}</span>
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) auto', columnGap: 10, alignItems: 'center', paddingTop: 12, borderTop: ROW_RULE }}>
        <span>
          <span style={{ display: 'block', fontSize: 13.5, fontWeight: 700 }}>Echo</span>
          <span style={META}>answer engines &middot; checked {newest ? `${ageOf(newest)} ago` : '-'}</span>
        </span>
        <span style={{ display: 'inline-flex', alignItems: 'center', gap: 4 }}>
          {latest.map((x, i) => <span key={i} style={{ width: 8, height: 8, borderRadius: 4, background: x.ok ? H.okBar : H.dangerBar }} />)}
          <span style={{ marginLeft: 6, fontSize: 13, fontWeight: 800 }}>{latest.length ? `${okN}/${latest.length}` : '-'}</span>
        </span>
      </div>
    </Panel>
  );
}

/** The StabilityTab pipe test, restyled. trackError dedupes repeats, so the button rests 15s. */
function CheckTracking({ a, refetch }: { a: HealthApp | undefined; refetch: () => void }) {
  const [cool, setCool] = useState(false);
  const timers = useRef<number[]>([]);
  useEffect(() => () => timers.current.forEach(clearTimeout), []);
  const send = () => {
    trackError({ kind: 'test', message: 'Admin pipe test' });
    setCool(true);
    timers.current.push(window.setTimeout(refetch, 5_000));
    timers.current.push(window.setTimeout(() => setCool(false), 15_000));
  };
  return (
    <section style={{ borderRadius: 16, padding: '14px 16px', boxShadow: `inset 0 0 0 1px ${t.line}`, display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) auto', columnGap: 12, alignItems: 'center' }}>
      <span>
        <span style={{ display: 'block', fontSize: 13.5, fontWeight: 700 }}>Check error tracking</span>
        <span style={{ display: 'block', marginTop: 2, fontSize: 11, lineHeight: 1.45, color: t.inkFaint }}>Sends a harmless test error through the whole pipeline</span>
        {a && (
          <span style={{ display: 'block', marginTop: 2, fontSize: 11, lineHeight: 1.45, color: t.inkFaint }}>
            {a.last_test_at ? `Last test received ${ageOf(a.last_test_at)} ago` : 'No test received in 14 days'}
          </span>
        )}
      </span>
      <button type="button" onClick={send} disabled={cool} style={{
        height: 36, padding: '0 14px', borderRadius: 999, border: 0, background: t.brandSoft, color: t.brandText,
        fontSize: 12, fontWeight: 800, fontFamily: 'inherit', cursor: cool ? 'default' : 'pointer', opacity: cool ? 0.6 : 1,
      }}>{cool ? 'Sent' : 'Send test'}</button>
    </section>
  );
}

export default function AppLens() {
  const app = useHealthApp();
  return (
    <>
      <Slot q={app} height={150}>{(a) => <CrashFree a={a} />}</Slot>
      <Slot q={app} height={330}>{(a) => <Builds a={a} />}</Slot>
      <Slot q={app} height={300}>{(a) => <Errors a={a} />}</Slot>
      <Services />
      <CheckTracking a={app.data} refetch={() => { void app.refetch(); }} />
    </>
  );
}

src/features/admin/components/health/Gol:
/** Health: Golf data lens (health_golf_data.html). */
import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useMutation } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { toast } from '@/lib/toast';
import { adminTheme as t } from '../../theme';
import ConfirmDialog from '../ConfirmDialog';
import { FooterButton, Head, Muted, Panel, ROW_RULE, Slot, FIG_LABEL } from '../analytics/analyticsUi';
import { dateLabel, num } from '../analytics/analyticsFormat';
import { useHealthGolf, useHealthJobs, type HealthGolf } from '../../hooks/useHealthLenses';
import { ageOf, ageSecs, minsText, plural, secsText } from './healthText';
import { Bar, H, META, PillButton } from './healthUi';
import { nextSyncText } from './cronText';

const share = (a: number | null, b: number | null) => (a == null || !b ? 0 : (100 * a) / b);

function Journey({ g }: { g: HealthGolf }) {
  const j = g.journey;
  const posted = j.posted ?? 0;
  const gap = (lag: React.ReactNode, note?: string | null) => (
    <div style={{ display: 'flex', alignItems: 'center', gap: 8, padding: '5px 0 5px 10px', fontSize: 10.5, fontWeight: 700, color: t.inkFaint }}>
      <span style={{ width: 1, height: 14, background: H.rule }} />
      {lag}
      <span>{note}</span>
    </div>
  );
  const diff = (a: number | null, b: number | null) => (a != null && b != null && a - b > 0 ? a - b : 0);
  const rows: { label: string; n: number | null; gap?: React.ReactNode }[] = [
    { label: 'Posted on England Golf', n: j.posted },
    { label: 'Synced to clbhouz', n: j.posted, gap: gap(<span style={{ color: H.okText }}>median {minsText(j.synced_median_mins)}</span>) },
    { label: 'Hole by hole fetched', n: j.holes, gap: gap(<span />, diff(j.posted, j.holes) ? `· ${diff(j.posted, j.holes)} posted without holes` : null) },
    { label: 'Course matched', n: j.matched, gap: gap(<span />, diff(j.analysed, j.matched) ? `· ${diff(j.analysed, j.matched)} on unmatched courses` : null) },
    { label: 'Analysed', n: j.analysed, gap: gap(<span style={{ color: H.okText }}>median {secsText(j.analysed_median_secs)}</span>) },
    {
      label: 'Seen by the member', n: j.seen,
      gap: gap(<span style={{ color: t.inkMuted }}>median {j.seen_median_mins == null ? '-' : j.seen_median_mins < 60 ? `${Math.round(j.seen_median_mins)}m` : `${Math.floor(j.seen_median_mins / 60)}h`}</span>,
        diff(j.analysed, j.seen) ? `· ${diff(j.analysed, j.seen)} not opened yet` : null),
    },
  ];
  return (
    <Panel>
      <Head title="A round's journey" side="last 7 days" />
      <div style={{ marginTop: 4, fontSize: 11.5, color: t.inkMuted }}>Every round posted by a connected member, from England Golf to their screen</div>
      {posted === 0 ? (
        <Muted style={{ marginTop: 12 }}>No rounds posted in 7 days.</Muted>
      ) : (
        <div style={{ marginTop: 12, display: 'flex', flexDirection: 'column' }}>
          {rows.map((r, i) => (
            <div key={r.label}>
              {r.gap}
              <div style={{ display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) auto', columnGap: 10, alignItems: 'baseline' }}>
                <span style={{ fontSize: 13, fontWeight: 700 }}>{r.label}</span>
                <span style={{ fontSize: 16, fontWeight: 800 }}>{num(r.n)}</span>
              </div>
              <Bar pct={Math.max(2, share(r.n, posted))} color={i === 0 ? H.inkSoft : H.brand} />
            </div>
          ))}
        </div>
      )}
    </Panel>
  );
}

function Connections({ g }: { g: HealthGolf }) {
  const c = g.connections;
  const next = nextSyncText(useHealthJobs().data, new Date());
  const tile = (label: string, v: number | null, sub: string, kind: 'fresh' | 'warn') => {
    const hot = kind === 'warn' && (v ?? 0) > 0;
    return (
      <div style={{ borderRadius: 12, padding: 10, background: hot ? H.tileWarn : H.tile }}>
        <div style={FIG_LABEL}>{label}</div>
        <div style={{ marginTop: 2, fontSize: 18, fontWeight: 800, color: kind === 'fresh' ? H.okText : hot ? H.amber : t.ink }}>{num(v)}</div>
        <div style={{ fontSize: 9.5, color: t.inkFaint }}>{sub}</div>
      </div>
    );
  };
  return (
    <Panel>
      <Head title="England Golf connections" side={next.text} sideStyle={next.tone ? { color: next.tone } : undefined} />
      <div style={{ marginTop: 8, display: 'flex', alignItems: 'baseline', gap: 8 }}>
        <span style={{ fontSize: 32, fontWeight: 800, letterSpacing: '-0.02em', lineHeight: 1 }}>{num(c.connected)}</span>
        <span style={{ fontSize: 13, fontWeight: 600, color: t.inkMuted }}>members connected</span>
      </div>
      <div style={{ marginTop: 12, display: 'grid', gridTemplateColumns: 'repeat(4, minmax(0, 1fr))', gap: 6 }}>
        {tile('Fresh', c.fresh, 'under 12h', 'fresh')}
        {tile('Stale', c.stale, 'over 12h', 'warn')}
        {tile('Re-auth', c.reauth, 'login expired', 'warn')}
        {tile('Failing', c.failing, '3+ in a row', 'warn')}
      </div>
      {c.oldest.length > 0 && (
        <>
          <div style={{ marginTop: 14, ...FIG_LABEL }}>Longest since a sync</div>
          <div style={{ marginTop: 4 }}>
            {c.oldest.slice(0, 3).map((m) => (
              <Link key={m.user_id} to={`/admin-v2/users?member=${m.user_id}`} style={{
                display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) auto', columnGap: 10, alignItems: 'center', padding: '9px 0', borderTop: ROW_RULE, color: t.ink, textDecoration: 'none',
              }}>
                <span style={{ minWidth: 0 }}>
                  <span style={{ display: 'block', fontSize: 13, fontWeight: 700 }}>{m.name ?? '-'}</span>
                  <span style={META}>
                    last round {dateLabel(m.last_round)} &middot; {m.rounds == null ? '-' : plural(m.rounds, 'round')}
                    {m.status === 'auth_failed' ? ' · login expired' : ''}
                  </span>
                </span>
                <span style={{ fontSize: 12, fontWeight: 800 }}>{m.last_synced_at ? `${ageOf(m.last_synced_at)} ago` : 'never'}</span>
              </Link>
            ))}
          </div>
        </>
      )}
    </Panel>
  );
}

function Quality({ g }: { g: HealthGolf }) {
  const q = g.quality;
  const row = (label: string, a: number | null, b: number | null, missing: number | null, sub: (n: number) => string) => {
    const p = a == null || !b ? null : Math.floor((100 * a) / b);
    const good = p != null && p >= 95;
    return (
      <div key={label}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'baseline' }}>
          <span style={{ fontSize: 12.5, fontWeight: 700 }}>{label}</span>
          <span style={{ fontSize: 14, fontWeight: 800, color: p == null ? t.ink : good ? H.okText : H.amber }}>{p == null ? '-' : `${p}%`}</span>
        </div>
        <Bar pct={p ?? 0} color={good ? H.okBar : H.amber} />
        <div style={{ marginTop: 3, fontSize: 10.5, color: t.inkFaint }}>{missing == null ? '-' : missing === 0 ? 'None missing' : sub(missing)}</div>
      </div>
    );
  };
  const less = (a: number | null, b: number | null) => (a == null || b == null ? null : Math.max(0, a - b));
  return (
    <Panel>
      <Head title="Data quality" side={q.rounds == null ? '- rounds on record' : `${plural(q.rounds, 'round')} on record`} />
      <div style={{ marginTop: 4, fontSize: 11.5, color: t.inkMuted }}>What every analysis depends on. Below 95% shows in amber.</div>
      <div style={{ marginTop: 12, display: 'flex', flexDirection: 'column', gap: 12 }}>
        {row('Hole by hole detail', q.hole_detail, q.rounds, less(q.rounds, q.hole_detail), (n) => `${plural(n, 'round')} ${n === 1 ? 'has' : 'have'} only a total score`)}
        {row('Course matched', q.course_matched, q.rounds, less(q.rounds, q.course_matched), (n) => `${plural(n, 'round')} on ${g.unmatched.courses == null ? '-' : plural(g.unmatched.courses, 'unmatched course')}`)}
        {row('Rating and slope', q.rating_slope, q.rounds, less(q.rounds, q.rating_slope), (n) => `${plural(n, 'round')} missing a course rating`)}
        {row('Course on the map', q.played_on_map, q.played_courses, less(q.played_courses, q.played_on_map), (n) => `${plural(n, 'played course')} ${n === 1 ? 'has' : 'have'} no location`)}
      </div>
    </Panel>
  );
}

function ToMatch({ g }: { g: HealthGolf }) {
  const nav = useNavigate();
  const u = g.unmatched;
  return (
    <Panel list>
      <div style={{ padding: '0 16px 10px' }}>
        <div style={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between' }}>
          <span style={{ fontSize: 11, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase' }}>Courses to match</span>
          {(u.courses ?? 0) > 0 && (
            <span style={{ fontSize: 11, fontWeight: 700, color: H.amber }}>{plural(u.courses!, 'course')} &middot; {u.rounds == null ? '-' : plural(u.rounds, 'round')}</span>
          )}
        </div>
        <div style={{ marginTop: 4, fontSize: 11.5, color: t.inkMuted }}>Rounds played here have no course page, stats or ratings until matched</div>
      </div>
      {!u.courses ? (
        <Muted style={{ padding: '10px 16px 12px', borderTop: ROW_RULE }}>Every played course is matched.</Muted>
      ) : (
        <>
          {u.rows.slice(0, 3).map((r, i) => (
            <div key={i} style={{ display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) auto', columnGap: 10, alignItems: 'center', padding: '10px 16px', borderTop: ROW_RULE }}>
              <span style={{ minWidth: 0 }}>
                <span style={{ display: 'block', fontSize: 13, fontWeight: 700 }}>{r.name}</span>
                <span style={META}>
                  {r.rounds == null ? '-' : plural(r.rounds, 'round')} &middot; {r.members == null ? '-' : plural(r.members, 'member')} &middot; last {dateLabel(r.last_played)}
                </span>
              </span>
              <Link to="/admin-v2/inbox/matching" style={{
                height: 32, padding: '0 12px', borderRadius: 999, border: `1px solid ${H.rule}`, display: 'inline-flex', alignItems: 'center',
                fontSize: 11.5, fontWeight: 700, color: t.ink, textDecoration: 'none',
              }}>Match</Link>
            </div>
          ))}
          <FooterButton onClick={() => nav('/admin-v2/inbox/matching')}>Open course matching</FooterButton>
        </>
      )}
    </Panel>
  );
}

function Stuck({ g }: { g: HealthGolf }) {
  const s = g.stuck; const j = g.journey;
  const clear = (s.stuck ?? 0) === 0 && (s.failed_7d ?? 0) === 0 && j.analysed === j.posted;
  const isStuck = (s.stuck ?? 0) > 0;
  const side = clear ? <span style={{ color: H.okText, fontWeight: 700 }}>none</span>
    : isStuck ? <span style={{ color: H.dangerText, fontWeight: 700 }}>{s.stuck} stuck</span>
    : <span style={{ color: H.amber, fontWeight: 700 }}>check</span>;
  const pending = Math.max(0, (j.posted ?? 0) - (j.analysed ?? 0));
  const body = clear
    ? `Every round posted in the last 7 days has been analysed. Median analysis time ${secsText(s.median_process_secs)}.`
    : isStuck
      ? `${plural(s.stuck!, 'round')} ${s.stuck === 1 ? 'has' : 'have'} waited over an hour, the oldest ${ageSecs(s.oldest_wait_secs)}.`
      : `${plural(pending, 'round')} from the last 7 days ${pending === 1 ? 'has' : 'have'} no analysis yet${(s.failed_7d ?? 0) > 0 ? `, ${s.failed_7d} failed` : ''}`;
  return (
    <Panel>
      <Head title="Stuck rounds" side={side} />
      <div style={{ marginTop: 8, display: 'flex', alignItems: 'center', gap: 10 }}>
        {clear && (
          <span style={{ width: 28, height: 28, borderRadius: 14, background: 'rgba(61,220,145,0.12)', display: 'grid', gridTemplateColumns: 'minmax(0, 1fr)', placeItems: 'center', flexShrink: 0 }}>
            <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke={H.okText} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M3.5 8.5l3 3 6-7" /></svg>
          </span>
        )}
        <span style={{ fontSize: 12.5, lineHeight: 1.4, color: t.inkMuted }}>{body}</span>
      </div>
    </Panel>
  );
}


/** Moved from SystemPage's DevToolsTab: same edge function calls, dialog and toasts. */
function FixTools() {
  const [confirm, setConfirm] = useState(false);
  const [clubId, setClubId] = useState('');
  const backfill = useMutation({
    mutationFn: async () => {
      const { data, error } = await supabase.functions.invoke('backfill-whs-course-mapping', { body: {} });
      if (error) throw error;
      return data;
    },
    onSuccess: (data: any) => {
      const summary = data?.matched != null ? `Matched ${data.matched}, unmatched ${data.unmatched ?? 0}` : 'Backfill complete.';
      toast.success('WHS backfill finished', { description: summary });
    },
    onError: (e: any) => toast.error('Backfill failed', { description: e?.message ?? 'Unknown error' }),
    onSettled: () => setConfirm(false),
  });
  const geocode = useMutation({
    mutationFn: async (id: string) => {
      const { data, error } = await supabase.functions.invoke('geocode-club', { body: { club_id: id } });
      if (error) throw error;
      return data;
    },
    onSuccess: (data: any) => toast.success('Club geocoded', {
      description: data?.latitude ? `Lat ${data.latitude}, Lng ${data.longitude}` : 'Coordinates persisted.',
    }),
    onError: (e: any) => toast.error('Geocode failed', { description: e?.message ?? 'Unknown error' }),
  });
  const id = clubId.trim();
  return (
    <Panel>
      <Head title="Fix tools" />
      <div style={{ marginTop: 10, display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) auto', columnGap: 10, alignItems: 'center', paddingBottom: 12, borderBottom: ROW_RULE }}>
        <span>
          <span style={{ display: 'block', fontSize: 13, fontWeight: 700 }}>Re-link England Golf courses</span>
          <span style={META}>Matches WHS courses to course pages again</span>
        </span>
        <PillButton primary disabled={backfill.isPending} onClick={() => setConfirm(true)}>{backfill.isPending ? 'Running…' : 'Run'}</PillButton>
      </div>
      <div style={{ paddingTop: 12 }}>
        <label htmlFor="health-club-id" style={{ display: 'block', fontSize: 13, fontWeight: 700 }}>Find a club's location</label>
        <span style={META}>Looks up the map position for a club from its id</span>
        <div style={{ marginTop: 8, display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) auto', gap: 8 }}>
          <input id="health-club-id" value={clubId} onChange={(e) => setClubId(e.target.value)} placeholder="Club id" style={{
            height: 40, boxSizing: 'border-box', padding: '0 12px', borderRadius: 12, border: `1px solid ${t.line}`,
            background: t.canvas, color: t.ink, fontSize: 13, fontFamily: 'inherit', minWidth: 0, outline: 'none',
          }} />
          <PillButton disabled={!id || geocode.isPending} onClick={() => geocode.mutate(id)} style={{ height: 40, borderRadius: 12 }}>
            {geocode.isPending ? 'Looking…' : 'Look up'}
          </PillButton>
        </div>
      </div>
      <ConfirmDialog
        open={confirm}
        onClose={() => setConfirm(false)}
        onConfirm={() => backfill.mutate()}
        busy={backfill.isPending}
        title="Run WHS backfill?"
        description="This will re-process WHS course mappings against golf_courses. Safe to re-run but may take a moment."
        confirmLabel="Run backfill"
      />
    </Panel>
  );
}

export default function GolfDataLens() {
  const golf = useHealthGolf();
  return (
    <>
      <Slot q={golf} height={420}>{(g) => <Journey g={g} />}</Slot>
      <Slot q={golf} height={330}>{(g) => <Connections g={g} />}</Slot>
      <Slot q={golf} height={300}>{(g) => <Quality g={g} />}</Slot>
      <Slot q={golf} height={240}>{(g) => <ToMatch g={g} />}</Slot>
      <Slot q={golf} height={96}>{(g) => <Stuck g={g} />}</Slot>
      <FixTools />
    </>
  );
}

src/features/admin/components/health/Job:
/** Health: Jobs lens (health_jobs.html). */
import React, { useState } from 'react';
import { adminTheme as t } from '../../theme';
import ConfirmDialog from '../ConfirmDialog';
import AdminSheet from '../AdminSheet';
import { Fig, FooterButton, Head, Muted, Panel, ROW_RULE, Slot, FIG_LABEL, KICKER } from '../analytics/analyticsUi';
import { num } from '../analytics/analyticsFormat';
import {
  useHealthJobs, useHealthLog, useRunJob, useSetJobActive,
  type HealthJob, type HealthJobs, type HealthLogRow, type LogKind,
} from '../../hooks/useHealthLenses';
import { useDeletionIntegrity } from '../../hooks/useDeletionIntegrity';
import { dayMonHM, describeSchedule, nextRun } from './cronText';
import { jobName } from './jobNames';
import { isMissed } from './healthIssues';
import { hasDetails, logLetter, logMeta, logTitle } from './healthLog';
import { ageOf, londonDayMon } from './healthText';
import { H, META, PillButton } from './healthUi';

type Problem = 'never_ok' | 'failing' | 'missed';
const problemOf = (j: HealthJob, from: string | null): Problem | null =>
  j.state === 'never_ok' ? 'never_ok' : j.state === 'failing' ? 'failing' : isMissed(j, from) ? 'missed' : null;

function ScheduleText({ schedule }: { schedule: string }) {
  const w = describeSchedule(schedule);
  return w.mono ? <span style={{ fontFamily: H.mono }}>{w.text}</span> : <>{w.text}</>;
}

const nextText = (j: HealthJob) => (j.active ? dayMonHM(nextRun(j.schedule)) : 'paused');

function JobActions({ job }: { job: HealthJob }) {
  const [ask, setAsk] = useState<'run' | 'pause' | null>(null);
  const run = useRunJob();
  const setActive = useSetJobActive();
  const name = jobName(job.name).name;
  return (
    <>
      <div style={{ marginTop: 10, display: 'flex', gap: 8 }}>
        <PillButton primary disabled={run.isPending} onClick={() => setAsk('run')}>Run now</PillButton>
        <PillButton disabled={setActive.isPending} onClick={() => setAsk('pause')}>{job.active ? 'Pause job' : 'Resume job'}</PillButton>
      </div>
      <ConfirmDialog
        open={ask === 'run'}
        onClose={() => setAsk(null)}
        busy={run.isPending}
        onConfirm={() => run.mutate({ id: job.id, name: job.name }, { onSettled: () => setAsk(null) })}
        title={`Run ${name} now?`}
        description="It runs exactly as if it were scheduled now, including anything it writes."
        confirmLabel="Run now"
      />
      <ConfirmDialog
        open={ask === 'pause'}
        onClose={() => setAsk(null)}
        busy={setActive.isPending}
        onConfirm={() => setActive.mutate({ id: job.id, name: job.name, active: !job.active }, { onSettled: () => setAsk(null) })}
        title={job.active ? `Pause ${name}?` : `Resume ${name}?`}
        description={job.active ? 'It will not run again until you resume it.' : 'It runs again on its schedule.'}
        confirmLabel={job.active ? 'Pause job' : 'Resume job'}
      />
    </>
  );
}

function lastRunText(j: HealthJob, from: string | null): string {
  if (!j.last_run_at) return `not since ${londonDayMon(from)}`;
  return `${londonDayMon(j.last_run_at)}, ${j.last_status === 'failed' ? 'failed' : 'ok'}`;
}

function Figures({ d }: { d: HealthJobs }) {
  const neverOk = d.jobs.filter((j) => j.state === 'never_ok').length;
  const failing = d.jobs.filter((j) => j.state === 'failing').length;
  const missed = d.jobs.filter((j) => isMissed(j, d.history_from)).length;
  const bad = neverOk + failing + missed;
  const sub = neverOk > 0 ? 'never succeeded' : missed > 0 && !failing ? 'missed a run' : 'last run failed';
  return (
    <Panel style={{ display: 'grid', gridTemplateColumns: 'repeat(3, minmax(0, 1fr))', gap: 6 }}>
      <Fig label="Jobs" value={num(d.total)} sub="scheduled" />
      <Fig label="Healthy" value={num(d.healthy)} sub="last run ok" valueColor={H.okText} />
      <Fig label="Failing" value={bad} sub={sub} valueColor={bad ? H.amber : H.okText} />
    </Panel>
  );
}

const PROBLEM_LABEL: Record<Problem, { text: string; color: string }> = {
  never_ok: { text: 'Never succeeded', color: H.dangerText },
  failing: { text: 'Failed last run', color: H.dangerText },
  missed: { text: 'Missed a run', color: H.amber },
};

function JobBlock({ j, from, problem }: { j: HealthJob; from: string | null; problem: Problem | null }) {
  const info = jobName(j.name);
  const err = j.last_error?.split('\n')[0]?.trim() || 'none recorded';
  return (
    <div style={{ padding: '12px 16px', borderTop: ROW_RULE }}>
      <div style={{ display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) auto', columnGap: 10, alignItems: 'baseline' }}>
        <span style={{ fontSize: 14, fontWeight: 700 }}>{info.name}</span>
        {problem && <span style={{ fontSize: 10, fontWeight: 800, letterSpacing: '0.08em', textTransform: 'uppercase', color: PROBLEM_LABEL[problem].color }}>{PROBLEM_LABEL[problem].text}</span>}
      </div>
      <div style={{ marginTop: 3, fontSize: 11, color: t.inkFaint }}>
        <span style={{ fontFamily: H.mono }}>{j.name}</span> &middot; <ScheduleText schedule={j.schedule} />
      </div>
      {info.what && <div style={{ marginTop: 6, fontSize: 12, lineHeight: 1.45, color: t.inkMuted }}>{info.what}</div>}
      <div style={{ marginTop: 8, display: 'grid', gridTemplateColumns: 'repeat(3, minmax(0, 1fr))', gap: 6, fontSize: 11 }}>
        <span><span style={{ display: 'block', ...FIG_LABEL }}>Last run</span>{lastRunText(j, from)}</span>
        <span><span style={{ display: 'block', ...FIG_LABEL }}>Next</span>{nextText(j)}</span>
        <span style={{ minWidth: 0, overflowWrap: 'anywhere' }}><span style={{ display: 'block', ...FIG_LABEL }}>Error</span>{err}</span>
      </div>
      <JobActions job={j} />
    </div>
  );
}

function NeedsAttention({ d }: { d: HealthJobs }) {
  const list = d.jobs.map((j) => ({ j, p: problemOf(j, d.history_from) })).filter((x) => x.p);
  if (!list.length) return null;
  return (
    <Panel list>
      <div style={{ padding: '0 16px 10px' }}><span style={{ ...KICKER, color: H.amber }}>Needs attention</span></div>
      {list.map(({ j, p }) => <JobBlock key={j.id} j={j} from={d.history_from} problem={p} />)}
    </Panel>
  );
}

function runColor(s: string | null): string {
  if (s == null) return H.track;
  if (s === 'succeeded') return H.okBar;
  if (s === 'failed') return H.dangerBar;
  return H.amber;
}

function rowStatus(j: HealthJob): string {
  if (!j.active) return 'paused';
  if (!j.last_run_at) return 'not run yet';
  if (j.last_status === 'failed') return `failed ${londonDayMon(j.last_run_at)}`;
  return `ran ${ageOf(j.last_run_at)} ago`;
}

function AllJobs({ d }: { d: HealthJobs }) {
  const [open, setOpen] = useState<HealthJob | null>(null);
  const live = open ? d.jobs.find((x) => x.id === open.id) ?? open : null;
  return (
    <Panel list>
      <Head inset title="All jobs" side="last 10 runs" />
      {!d.jobs.length && <Muted style={{ padding: '10px 16px', borderTop: ROW_RULE }}>No scheduled jobs.</Muted>}
      {d.jobs.map((j) => {
        const recent = j.recent.slice(-10);
        const cells: (string | null)[] = [...Array(10 - recent.length).fill(null), ...recent];
        const quietNotRun = j.state === 'not_run' && j.active && !isMissed(j, d.history_from);
        return (
          <button key={j.id} type="button" onClick={() => setOpen(j)} style={{
            display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) auto', columnGap: 10, alignItems: 'center', padding: '10px 16px',
            border: 0, borderTop: ROW_RULE, background: 'transparent', color: t.ink, width: '100%', textAlign: 'left', fontFamily: 'inherit', cursor: 'pointer',
          }}>
            <span style={{ minWidth: 0 }}>
              <span style={{ display: 'block', fontSize: 13, fontWeight: 700 }}>{jobName(j.name).name}</span>
              <span style={META}>
                <ScheduleText schedule={j.schedule} /> &middot; {quietNotRun ? `next ${dayMonHM(nextRun(j.schedule))}` : rowStatus(j)}
              </span>
            </span>
            <span style={{ display: 'inline-flex', gap: 3 }}>
              {cells.map((c, i) => <span key={i} style={{ width: 7, height: 14, borderRadius: 2, background: runColor(c) }} />)}
            </span>
          </button>
        );
      })}
      <AdminSheet open={!!live} onClose={() => setOpen(null)} title={live ? jobName(live.name).name : ''} subtitle={live?.name}>
        {live && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 12, color: t.ink }}>
            <div style={{ fontSize: 12, color: t.inkMuted }}>
              <ScheduleText schedule={live.schedule} /> &middot; next {nextText(live)}
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, minmax(0, 1fr))', gap: 6 }}>
              <Fig label="Runs" value={num(live.runs)} sub={`since ${londonDayMon(d.history_from)}`} />
              <Fig label="Ok" value={num(live.ok)} valueColor={H.okText} />
              <Fig label="Failed" value={num(live.failed)} valueColor={(live.failed ?? 0) > 0 ? H.dangerText : undefined} />
              <Fig label="Last took" value={live.last_secs == null ? '-' : `${Math.round(live.last_secs * 10) / 10}s`} />
            </div>
            <div>
              <div style={FIG_LABEL}>Last error</div>
              <pre style={{ margin: '4px 0 0', whiteSpace: 'pre-wrap', overflowWrap: 'anywhere', fontFamily: H.mono, fontSize: 11.5, color: t.inkMuted }}>
                {live.last_error || 'none recorded'}
              </pre>
            </div>
            <JobActions job={live} />
          </div>
        )}
      </AdminSheet>
    </Panel>
  );
}

function Deletions() {
  const del = useDeletionIntegrity();
  if (del.isLoading) return <Panel style={{ height: 92 }}><span /></Panel>;
  const d = del.data;
  const live = d?.live_sessions ?? null; const unb = d?.unbanned ?? null;
  const need = (live ?? 0) + (unb ?? 0);
  const hot = (v: number | null) => (v != null && v > 0 ? H.dangerText : undefined);
  return (
    <Panel>
      <Head title="Account deletions" side={!d ? '-' : need === 0 ? 'all erased' : `${need} need action`}
        sideStyle={{ fontWeight: 700, color: !d ? t.inkFaint : need === 0 ? H.okText : H.dangerText }} />
      <div style={{ marginTop: 10, display: 'grid', gridTemplateColumns: 'repeat(3, minmax(0, 1fr))', gap: 6 }}>
        <Fig label="Still signed in" value={num(live)} valueColor={hot(live)} />
        <Fig label="Not erased" value={num(unb)} valueColor={hot(unb)} />
        <Fig label="Erased" value={num(d?.orphan_profiles)} />
      </div>
    </Panel>
  );
}

const CHIPS: { id: LogKind; label: string }[] = [
  { id: 'all', label: 'All' }, { id: 'courses', label: 'Courses' }, { id: 'accounts', label: 'Accounts' }, { id: 'content', label: 'Content' },
];

function AdminLog() {
  const [kind, setKind] = useState<LogKind>('all');
  const [open, setOpen] = useState<HealthLogRow | null>(null);
  const log = useHealthLog(kind);
  const rows = log.data?.pages.flatMap((p) => p.rows) ?? [];
  return (
    <Panel list>
      <Head inset title="Admin log" side="who did what" />
      <div style={{ display: 'flex', gap: 6, padding: '0 16px 12px' }}>
        {CHIPS.map((c) => {
          const on = c.id === kind;
          return (
            <button key={c.id} type="button" onClick={() => setKind(c.id)} aria-pressed={on} style={{
              height: 30, padding: '0 12px', borderRadius: 999, border: 0, fontSize: 11.5, fontWeight: 700, fontFamily: 'inherit', cursor: 'pointer',
              background: on ? t.ink : H.chip, color: on ? t.canvas : t.ink,
            }}>{c.label}</button>
          );
        })}
      </div>
      {log.isLoading && <div style={{ height: 180 }} />}
      {log.isError && !log.data && (
        <div style={{ padding: '10px 16px', borderTop: ROW_RULE, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <Muted>Couldn't load the log.</Muted>
          <PillButton onClick={() => { void log.refetch(); }}>Retry</PillButton>
        </div>
      )}
      {log.data && !rows.length && <Muted style={{ padding: '10px 16px 12px', borderTop: ROW_RULE }}>Nothing logged yet.</Muted>}
      {rows.map((r) => {
        const ic = logLetter(r.kind);
        const clickable = hasDetails(r);
        const inner = (
          <>
            <span style={{ width: 28, height: 28, borderRadius: 14, display: 'grid', gridTemplateColumns: 'minmax(0, 1fr)', placeItems: 'center', fontSize: 11, fontWeight: 800, color: t.canvas, background: ic.bg }}>{ic.letter}</span>
            <span style={{ minWidth: 0 }}>
              <span style={{ display: 'block', fontSize: 13, fontWeight: 700 }}>{logTitle(r)}</span>
              <span style={{ ...META, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{logMeta(r) || '\u00a0'}</span>
            </span>
            <span style={{ fontSize: 11, color: t.inkFaint }}>{ageOf(r.at, Date.now(), true)}</span>
          </>
        );
        const style: React.CSSProperties = {
          display: 'grid', gridTemplateColumns: '28px minmax(0, 1fr) auto', columnGap: 10, alignItems: 'center', padding: '10px 16px',
          border: 0, borderTop: ROW_RULE, background: 'transparent', color: t.ink, width: '100%', textAlign: 'left', fontFamily: 'inherit',
        };
        return clickable
          ? <button key={r.id} type="button" onClick={() => setOpen(r)} style={{ ...style, cursor: 'pointer' }}>{inner}</button>
          : <div key={r.id} style={style}>{inner}</div>;
      })}
      {log.hasNextPage && (
        <FooterButton onClick={() => { void log.fetchNextPage(); }}>{log.isFetchingNextPage ? 'Loading…' : 'Show older'}</FooterButton>
      )}
      <AdminSheet open={!!open} onClose={() => setOpen(null)} title={open ? logTitle(open) : ''} subtitle={open ? logMeta(open) : undefined}>
        {open && (
          <pre style={{ margin: 0, whiteSpace: 'pre-wrap', overflowWrap: 'anywhere', fontFamily: H.mono, fontSize: 11.5, color: t.inkMuted }}>
            {JSON.stringify(open.details, null, 2)}
          </pre>
        )}
      </AdminSheet>
    </Panel>
  );
}

export default function JobsLens() {
  const jobs = useHealthJobs();
  return (
    <>
      <Slot q={jobs} height={78}>{(d) => <Figures d={d} />}</Slot>
      <Slot q={jobs} height={0}>{(d) => <NeedsAttention d={d} />}</Slot>
      <Slot q={jobs} height={640}>{(d) => <AllJobs d={d} />}</Slot>
      <Deletions />
      <AdminLog />
    </>
  );
}

src/features/admin/components/health/Sta:
/** Health: Status lens (health_status.html). */
import React from 'react';
import { Link } from 'react-router-dom';
import { adminTheme as t } from '../../theme';
import { Fig, Head, Muted, Panel, PanelError, PanelSkeleton, ROW_RULE, Slot, KICKER } from '../analytics/analyticsUi';
import { DAY_NAMES, londonHM, num } from '../analytics/analyticsFormat';
import { useHealthApp, useHealthGolf, useHealthJobs } from '../../hooks/useHealthLenses';
import { useEchoEngineHealth } from '../../hooks/useEchoEngineHealth';
import { usePushHealth } from '../../hooks/usePushHealth';
import { useDeletionIntegrity } from '../../hooks/useDeletionIntegrity';
import { useSystemStateHistory, type SystemDayState } from '../../hooks/useSystemStateHistory';
import { slowestText } from './healthText';
import { areaTone, jobProblems, useHealthVerdict, type Issue, type IssueArea } from './healthIssues';
import { lensLabel, type HealthLens } from './healthLens';
import { hoursMins, londonDayMon } from './healthText';
import { H } from './healthUi';

const lensHref = (l: HealthLens) => `/admin-v2/health?lens=${l}`;

const PALETTE = {
  ok: { bg: 'rgba(61,220,145,0.08)', ring: 'rgba(61,220,145,0.3)', dot: '#5FE3A8', kicker: '#5FE3A8', btn: '#5FE3A8' },
  warn: { bg: 'rgba(249,200,116,0.08)', ring: 'rgba(249,200,116,0.3)', dot: '#F9C874', kicker: '#F9C874', btn: '#F9C874' },
  danger: { bg: 'rgba(255,123,114,0.08)', ring: 'rgba(255,123,114,0.3)', dot: '#FF7B72', kicker: '#FF9B93', btn: '#FF9B93' },
};

function Verdict() {
  const v = useHealthVerdict();
  if (v.isLoading) return <PanelSkeleton height={176} />;
  if (v.isError) return <PanelError onRetry={v.retry} retrying={v.retrying} />;
  const issues = v.issues;
  const tone = !issues.length ? 'ok' : issues.some((i) => i.tone === 'danger') ? 'danger' : 'warn';
  const p = PALETTE[tone];
  const first = issues[0] as Issue | undefined;
  return (
    <section style={{ borderRadius: 16, padding: 16, background: p.bg, boxShadow: `inset 0 0 0 1px ${p.ring}` }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
        <span style={{ width: 8, height: 8, borderRadius: 4, background: p.dot }} />
        <span style={{ ...KICKER, color: p.kicker }}>
          {first ? `${issues.length} ${issues.length === 1 ? 'thing needs' : 'things need'} you` : 'All clear'}
        </span>
      </div>
      <div style={{ marginTop: 8, fontSize: 20, fontWeight: 800, letterSpacing: '-0.01em', lineHeight: 1.2 }}>
        {first ? first.title : 'Everything is running normally'}
      </div>
      {first?.body && <div style={{ marginTop: 6, fontSize: 12.5, lineHeight: 1.45, color: t.inkMuted }}>{first.body}</div>}
      {issues.length > 1 && (
        <div style={{ marginTop: 8, display: 'flex', flexDirection: 'column', gap: 4 }}>
          {issues.slice(1).map((i, k) => (
            <Link key={k} to={lensHref(i.lens)} style={{ fontSize: 12, color: t.inkMuted, textDecoration: 'none' }}>{i.title}</Link>
          ))}
        </div>
      )}
      <div style={{ marginTop: 12, display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 }}>
        <span style={{ fontSize: 11, color: t.inkFaint }}>Everything else normal &middot; checked {londonHM(v.checkedAt || null)}</span>
        {first && (
          <Link to={lensHref(first.lens)} style={{
            height: 34, padding: '0 14px', borderRadius: 999, background: p.btn, color: t.canvas, fontSize: 12, fontWeight: 800,
            display: 'inline-flex', alignItems: 'center', textDecoration: 'none', flexShrink: 0,
          }}>Open {lensLabel(first.lens)}</Link>
        )}
      </div>
    </section>
  );
}

/** 'YYYY-MM-DD' -> 'Mon'..'Sun' without new Date() on the calendar string. */
function dayName(d: string): string {
  const [y, m, dd] = d.slice(0, 10).split('-').map(Number);
  if (!y || !m || !dd) return '-';
  const dow = new Date(Date.UTC(y, m - 1, dd)).getUTCDay(); // UTC midnight of that calendar day
  return DAY_NAMES[(dow + 6) % 7];
}

function RoundToMember() {
  const golf = useHealthGolf();
  return (
    <Slot q={golf} height={262}>
      {(g) => {
        const p = g.promise;
        const over = p.median_hrs != null && p.median_hrs > p.target_hrs;
        const stuck = g.stuck.stuck;
        const scale = 10.5;
        return (
          <Panel>
            <Head title="Round to member" side={<>the promise &middot; 7 days</>} />
            <div style={{ marginTop: 8, display: 'flex', alignItems: 'baseline', gap: 10 }}>
              <span style={{ fontSize: 44, fontWeight: 800, letterSpacing: '-0.03em', lineHeight: 1 }}>{hoursMins(p.median_hrs)}</span>
              {p.median_hrs != null && (
                <span style={{ fontSize: 12, fontWeight: 800, padding: '3px 8px', borderRadius: 999, background: over ? H.warnChip : H.okChip, color: over ? H.amber : H.okText }}>
                  {over ? `over ${p.target_hrs}h` : `inside ${p.target_hrs}h`}
                </span>
              )}
            </div>
            <div style={{ marginTop: 6, fontSize: 12, lineHeight: 1.45, color: t.inkMuted }}>
              Median time from a score being posted on England Golf to its analysis being ready in clbhouz
            </div>
            <div style={{ marginTop: 14, position: 'relative', height: 70, display: 'grid', gridTemplateColumns: 'repeat(7, minmax(0, 1fr))', gap: 8, alignItems: 'end' }}>
              {p.days.slice(-7).map((d, i, all) => {
                const empty = !d.n;
                const today = i === all.length - 1;
                const late = d.median_hrs != null && d.median_hrs > p.target_hrs;
                const h = empty || d.median_hrs == null ? null : Math.min(100, Math.max(0, (d.median_hrs / scale) * 100));
                return (
                  <div key={d.d} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4, height: '100%', justifyContent: 'flex-end' }}>
                    <div style={{
                      width: '100%', borderRadius: '3px 3px 1px 1px',
                      height: h == null ? 2 : `${h}%`,
                      background: h == null ? H.track : late ? H.amber : today ? H.brand : H.inkSoft,
                    }} />
                  </div>
                );
              })}
              <div style={{ position: 'absolute', left: 0, right: 0, bottom: `${(p.target_hrs / scale) * 70}px`, borderTop: '1px dashed rgba(249,200,116,0.55)' }} />
              <span style={{ position: 'absolute', right: 0, bottom: `${(p.target_hrs / scale) * 70 + 3}px`, fontSize: 9.5, fontWeight: 700, color: H.amber }}>{p.target_hrs}h target</span>
            </div>
            <div style={{ marginTop: 4, display: 'grid', gridTemplateColumns: 'repeat(7, minmax(0, 1fr))', gap: 8, fontSize: 9.5, fontWeight: 700, color: t.inkFaint, textAlign: 'center' }}>
              {p.days.slice(-7).map((d) => <span key={d.d}>{dayName(d.d)}</span>)}
            </div>
            <div style={{ marginTop: 12, paddingTop: 10, borderTop: ROW_RULE, display: 'grid', gridTemplateColumns: 'repeat(3, minmax(0, 1fr))', gap: 6 }}>
              <Fig label="Rounds" value={num(p.rounds)} sub="this week" />
              <Fig label="Slowest" value={slowestText(p.slowest_hrs)} sub="one round" />
              <Fig label="Stuck" value={num(stuck)} sub="over 1h" valueColor={stuck == null ? undefined : stuck > 0 ? H.dangerText : H.okText} />
            </div>
          </Panel>
        );
      }}
    </Slot>
  );
}

const TONE = {
  ok: { dot: H.okBar, value: t.ink },
  warn: { dot: H.amber, value: H.amber },
  danger: { dot: H.dangerBar, value: H.dangerText },
};

function cellColor(s: SystemDayState): string {
  if (s === 'ok') return H.okBar;
  if (s === 'warn') return H.amber;
  if (s === 'danger') return H.dangerBar;
  return H.track;
}

function Systems() {
  const v = useHealthVerdict();
  const golf = useHealthGolf();
  const app = useHealthApp();
  const jobs = useHealthJobs();
  const echo = useEchoEngineHealth();
  const push = usePushHealth();
  const del = useDeletionIntegrity();
  const hist = useSystemStateHistory(14);

  if (v.isLoading) return <PanelSkeleton height={560} />;
  if (v.isError) return <PanelError onRetry={v.retry} retrying={v.retrying} />;

  const series = (id: string | null): SystemDayState[] => {
    const days = id ? hist.data?.systems.find((x) => x.subsystem === id)?.days ?? [] : [];
    const last = days.slice(-14);
    return [...Array(14 - last.length).fill(null), ...last];
  };
  const g = golf.data; const a = app.data;
  const jp = jobProblems(jobs.data);
  const nJobs = jp.neverOk.length + jp.failing.length + jp.missed.length;
  const latest = echo.data?.latest ?? [];
  const delN = del.data ? del.data.live_sessions + del.data.unbanned : null;

  const rows: { label: string; meta: string; value: string; area: IssueArea; hist: string | null; lens: HealthLens }[] = [
    { label: 'England Golf sync', meta: 'connections synced in 12h', value: g ? `${num(g.connections.fresh)}/${num(g.connections.connected)}` : '-', area: 'eg', hist: 'eg', lens: 'golf' },
    { label: 'Round analysis', meta: 'rounds waiting to be scored', value: g ? `${num(g.stuck.waiting)} waiting` : '-', area: 'pipeline', hist: 'pipeline', lens: 'golf' },
    { label: 'Course matching', meta: 'rounds on unmatched courses', value: g ? num(g.unmatched.rounds) : '-', area: 'matching', hist: null, lens: 'golf' },
    { label: 'Echo', meta: 'answer engines responding', value: latest.length ? `${latest.filter((x) => x.ok).length}/${latest.length}` : '-', area: 'echo', hist: 'echo', lens: 'app' },
    { label: 'Push', meta: 'failed in 24h', value: push.data ? num(push.data.queue.errored_24h) : '-', area: 'push', hist: 'push', lens: 'app' },
    { label: 'App errors', meta: 'current build, 7 days', value: a ? num(a.errors_7d_current) : '-', area: 'errors', hist: 'errors', lens: 'app' },
    {
      label: 'Scheduled jobs',
      meta: jp.neverOk.length ? 'never succeeded' : jp.failing.length ? 'failed last run' : jp.missed.length ? 'missed a run' : 'all running',
      value: !jobs.data ? '-' : nJobs ? `${nJobs} failing` : '0', area: 'jobs', hist: null, lens: 'jobs',
    },
    { label: 'Account deletions', meta: 'not fully erased', value: num(delN), area: 'deletion', hist: 'deletion', lens: 'jobs' },
  ];

  return (
    <Panel list>
      <Head inset title="Systems" side="last 14 days" />
      {rows.map((r) => {
        const tone = TONE[areaTone(v.issues, r.area)];
        return (
          <Link key={r.label} to={lensHref(r.lens)} style={{ display: 'block', padding: '11px 16px', borderTop: ROW_RULE, color: t.ink, textDecoration: 'none' }}>
            <div style={{ display: 'grid', gridTemplateColumns: '10px minmax(0, 1fr) auto', columnGap: 10, alignItems: 'center' }}>
              <span style={{ width: 8, height: 8, borderRadius: 4, background: tone.dot }} />
              <span style={{ minWidth: 0 }}>
                <span style={{ display: 'block', fontSize: 13.5, fontWeight: 700 }}>{r.label}</span>
                <span style={{ display: 'block', fontSize: 10.5, color: t.inkFaint }}>{r.meta}</span>
              </span>
              <span style={{ fontSize: 13, fontWeight: 800, color: tone.value }}>{r.value}</span>
            </div>
            <div style={{ marginTop: 8, marginLeft: 20, display: 'grid', gridTemplateColumns: 'repeat(14, minmax(0, 1fr))', gap: 3 }}>
              {series(r.hist).map((s, i) => <span key={i} style={{ height: 10, borderRadius: 2, background: cellColor(s) }} />)}
            </div>
          </Link>
        );
      })}
      <div style={{ display: 'flex', gap: 14, padding: '10px 16px 8px', borderTop: ROW_RULE, fontSize: 10.5, color: t.inkFaint }}>
        {([['normal', H.okBar], ['degraded', H.amber], ['down', H.dangerBar]] as const).map(([l, c]) => (
          <span key={l} style={{ display: 'inline-flex', alignItems: 'center', gap: 5 }}>
            <span style={{ width: 8, height: 8, borderRadius: 2, background: c }} />{l}
          </span>
        ))}
      </div>
    </Panel>
  );
}

const CHANGE_LABEL: Record<string, string> = {
  eg: 'England Golf sync', cron: 'England Golf sync timer', pipeline: 'Round analysis', echo: 'Echo',
  push: 'Push', errors: 'App errors', deletion: 'Account deletions',
};
const VERB = { ok: 'recovered', warn: 'degraded', danger: 'down' } as const;

function WhatChanged() {
  const hist = useSystemStateHistory(14);
  return (
    <Slot q={hist} height={220}>
      {(h) => {
        const rows = h.changes
          .filter((c) => c.tone !== 'idle')
          .sort((a, b) => (a.at < b.at ? 1 : a.at > b.at ? -1 : 0))
          .slice(0, 5);
        return (
          <Panel list>
            <Head inset title="What changed" side="14 days" />
            {!rows.length && <Muted style={{ padding: '10px 16px', borderTop: ROW_RULE }}>Nothing changed in 14 days.</Muted>}
            {rows.map((c, i) => (
              <div key={i} style={{ display: 'grid', gridTemplateColumns: '52px 12px minmax(0, 1fr)', columnGap: 8, alignItems: 'start', padding: '10px 16px', borderTop: ROW_RULE }}>
                <span style={{ fontSize: 11, fontWeight: 700, color: t.inkFaint }}>{londonDayMon(c.at)}</span>
                <span style={{ marginTop: 4, width: 8, height: 8, borderRadius: 4, background: cellColor(c.tone) }} />
                <span>
                  <span style={{ display: 'block', fontSize: 13, fontWeight: 700 }}>
                    {CHANGE_LABEL[c.subsystem] ?? c.subsystem} {VERB[c.tone as 'ok' | 'warn' | 'danger']}
                  </span>
                  {c.detail && <span style={{ display: 'block', marginTop: 2, fontSize: 11.5, lineHeight: 1.45, color: t.inkMuted }}>{c.detail}</span>}
                </span>
              </div>
            ))}
          </Panel>
        );
      }}
    </Slot>
  );
}

export default function StatusLens() {
  return (
    <>
      <Verdict />
      <RoundToMember />
      <Systems />
      <WhatChanged />
    </>
  );
}

