.bizc-sub{font-size:15px;line-height:1.5;color:var(--bizc-mute);margin-top:10px}
.bizc-group{font-size:10px;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:var(--bizc-dim);margin:20px 0 8px}
.bizc-tiles{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.bizc-tile{background:var(--bizc-card);border:1px solid var(--bizc-hair);border-radius:16px;padding:12px;min-height:50px;display:flex;align-items:center;gap:10px;font-size:14px;font-weight:600;color:var(--bizc-ink);text-align:left;min-width:0}
.bizc-tile svg{width:18px;height:18px;flex:none;color:var(--bizc-mute)}
.bizc-tile[aria-pressed=true]{border-color:rgba(248,250,252,0.5);background:#1C1C21}.bizc-tile[aria-pressed=true] svg{color:var(--bizc-ink)}
.bizc-foot{padding:14px 20px calc(34px + env(safe-area-inset-bottom,0px));display:flex;flex-direction:column;gap:4px}
.bizc-primary{height:52px;border-radius:999px;background:var(--bizc-ink);color:var(--bizc-canvas);font-size:16px;font-weight:600;width:100%;border:0}
.bizc-primary:disabled{opacity:.4}
.bizc-tile:focus-visible,.bizc-primary:focus-visible,.bizc-back:focus-visible{outline:2px solid #F7931E;outline-offset:2px}

/* BC2 step 2 — field cards, results, club card, facts, notes (biz-c2-find.html). */
.bizc-field{display:block;background:var(--bizc-card);border:1px solid var(--bizc-hair);border-radius:16px;padding:12px 14px;margin-top:10px}
.bizc-field:focus-within{border-color:rgba(248,250,252,0.32);background:#1B1B20}
.bizc-field-label{display:block;font-size:10px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:var(--bizc-dim)}
.bizc-field-input{width:100%;background:transparent;border:0;outline:0;color:var(--bizc-ink);font-size:16px;font-weight:600;margin-top:6px;padding:0;caret-color:var(--bizc-ink,#F8FAFC);font-family:inherit}
.bizc-field-input::placeholder{color:rgba(248,250,252,0.3);font-weight:500}
textarea.bizc-field-input{font-size:14.5px;font-weight:400;line-height:1.5;resize:none;min-height:66px}
.bizc-res{background:var(--bizc-card);border:1px solid var(--bizc-hair);border-radius:18px;margin-top:10px;padding:0 14px}
.bizc-res-row{display:flex;align-items:center;gap:12px;padding:11px 0;border:0;border-top:1px solid var(--bizc-hair);width:100%;background:none;color:inherit;text-align:left;cursor:pointer}
.bizc-res-row:first-child{border-top:0}
.bizc-thumb{width:44px;height:44px;border-radius:10px;flex:none;background:#1E1E23;display:flex;align-items:center;justify-content:center;color:var(--bizc-mute);overflow:hidden}
.bizc-thumb img{width:100%;height:100%;object-fit:cover}
.bizc-res-text{flex:1;min-width:0}
.bizc-res-name{display:block;font-size:15px;font-weight:600}
.bizc-res-place{display:block;font-size:12.5px;color:var(--bizc-mute);margin-top:2px}
.bizc-link{display:block;background:none;border:0;padding:0;font-size:14px;font-weight:600;color:var(--bizc-ink);margin-top:14px;cursor:pointer}
.bizc-card{background:var(--bizc-card);border:1px solid var(--bizc-hair);border-radius:18px;margin-top:14px;padding:16px}
.bizc-idrow{display:flex;align-items:center;gap:12px}
.bizc-clubcard{background:var(--bizc-card);border:1px solid var(--bizc-hair);border-radius:18px;margin-top:14px;overflow:hidden}
.bizc-clubcard-band{position:relative;height:96px;background:radial-gradient(120% 90% at 30% 25%,#3a3f4a 0%,#23262e 45%,#121317 100%)}
.bizc-clubcard-band img{width:100%;height:100%;object-fit:cover;display:block}
.bizc-clubcard-fade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(23,23,27,0) 30%,#17171B 100%)}
.bizc-clubcard-body{padding:0 16px 16px;margin-top:-22px;position:relative}
.bizc-clubcard-name{font-size:18px;font-weight:700;letter-spacing:-0.01em}
.bizc-clubcard-place{font-size:13.5px;line-height:1.5;color:var(--bizc-mute);margin-top:2px}
.bizc-facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin-top:14px;padding-top:14px;border-top:1px solid var(--bizc-hair)}
.bizc-facts>div{text-align:center;min-width:0}
.bizc-facts>div+div{border-left:1px solid var(--bizc-hair)}
.bizc-facts b{display:block;font-size:18px;font-weight:700;font-variant-numeric:tabular-nums}
.bizc-facts i{display:block;font-style:normal;font-size:9.5px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--bizc-dim);margin-top:5px}
.bizc-norounds{font-size:13.5px;color:var(--bizc-mute);margin-top:14px;padding-top:14px;border-top:1px solid var(--bizc-hair)}
.bizc-note{background:var(--bizc-card);border:1px solid var(--bizc-hair);border-radius:18px;margin-top:12px;padding:14px 16px}
.bizc-note b{display:block;font-size:15px;font-weight:600}
.bizc-note p{font-size:13.5px;line-height:1.5;color:var(--bizc-mute);margin-top:4px}
.bizc-hint{font-size:12.5px;color:var(--bizc-dim);margin-top:8px;line-height:1.45}
.bizc-textbtn{display:flex;align-items:center;justify-content:center;height:40px;width:100%;color:var(--bizc-mute);font-size:15px;font-weight:600;background:none;border:0;cursor:pointer}
.bizc-crest{width:44px;height:44px;border-radius:12px;background:#1E1E23;color:var(--bizc-mute);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:15px;flex:none;overflow:hidden}
.bizc-crest img{width:100%;height:100%;object-fit:cover}
.bizc-tick{font-size:12.5px;color:var(--bizc-mute);margin-top:8px}
.bizc-tick b{color:#34D399;font-weight:600}
.bizc-pillrow{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}
.bizc-ghost{display:inline-flex;align-items:center;justify-content:center;height:40px;border-radius:999px;background:rgba(255,255,255,0.07);border:1px solid rgba(255,255,255,0.14);font-size:14px;font-weight:600;color:var(--bizc-ink);padding:0 16px;cursor:pointer}
.bizc-ghost.plain{background:transparent}
/* BIZ_ADDRESS_COUNTRY_FIRST (address-step-signed-off.html) */
.bizc-steprow{display:flex;align-items:center;gap:7px}
.bizc-step{width:16px;height:16px;border-radius:50%;background:rgba(255,255,255,0.12);color:#F8FAFC;font-size:9.5px;font-weight:700;font-variant-numeric:tabular-nums lining-nums;display:inline-flex;align-items:center;justify-content:center;flex:none;line-height:1}
.bizc-step.done{background:#F8FAFC}
.bizc-pick{width:100%;text-align:left;color:inherit;font-family:inherit;cursor:pointer}
.bizc-pick-row{display:flex;align-items:center;gap:10px;margin-top:6px}
.bizc-pick-row svg{flex:none;color:rgba(248,250,252,0.62)}
.bizc-pick-value{flex:1;min-width:0;font-size:16px;font-weight:600;color:#F8FAFC;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.bizc-pick-value.empty{color:rgba(248,250,252,0.3);font-weight:500}
.bizc-field.locked{opacity:.42;cursor:pointer}
.bizc-lockline{display:flex;align-items:center;gap:6px;margin-top:8px;font-size:12.5px;color:rgba(248,250,252,0.62)}
.bizc-lockline svg{flex:none}
.bizc-cantfind{font-size:13px;color:rgba(248,250,252,0.62);margin-top:9px}
.bizc-cantfind button{background:none;border:0;padding:0;color:#F8FAFC;font-weight:600;font-size:13px;font-family:inherit;cursor:pointer}
.bizc-field{--addr-panel-inset-x:15px;--addr-panel-inset-y:13px}
.bizc-country{margin-top:8px}
.bizc-areakick{font-size:10px;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:var(--bizc-mute)}
.bizc-areahead{font-size:15.5px;font-weight:600;line-height:1.45;margin-top:8px}
.bizc-address{position:relative}
.bizc-address input{width:100%;background:transparent;border:0;outline:0;box-shadow:none;color:var(--bizc-ink);font-size:16px;font-weight:600;margin-top:6px;padding:0;height:auto;caret-color:var(--bizc-ink,#F8FAFC)}
.bizc-address input::placeholder{color:rgba(248,250,252,0.3);font-weight:500}
.bizc-address input:focus-visible{outline:0;box-shadow:none}
.bizc-link:focus-visible,.bizc-textbtn:focus-visible,.bizc-ghost:focus-visible,.bizc-res-row:focus-visible,.bizc-cline button:focus-visible{outline:2px solid #F7931E;outline-offset:2px}

/* BC3 step 3 — contact rows card, main-button chips, extras rows, sheets (biz-c3-contact.html). */
.bizc-rows{background:var(--bizc-card);border:1px solid var(--bizc-hair);border-radius:18px;padding:0 16px;margin-top:14px}
.bizc-rows:focus-within{border-color:rgba(248,250,252,0.32)}
.bizc-row{display:flex;align-items:center;gap:12px;min-height:52px;padding:13px 0;border-top:1px solid var(--bizc-hair)}
.bizc-row:first-child{border-top:0}
.bizc-row-label{width:70px;flex:none;font-size:10px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:var(--bizc-dim)}
.bizc-row-input{flex:1;min-width:0;background:transparent;border:0;outline:0;box-shadow:none;color:var(--bizc-ink);font-size:15px;font-weight:500;padding:0;caret-color:#fff;font-family:inherit}
.bizc-row-input::placeholder{color:rgba(248,250,252,0.3)}
.bizc-row-input:focus-visible{outline:0;box-shadow:none}
.bizc-error{font-size:12.5px;color:#E24B3F;margin-top:8px;line-height:1.45}
.bizc-dial{display:inline-flex;align-items:center;gap:6px;height:32px;padding:0 9px;border-radius:9px;background:rgba(255,255,255,0.06);border:1px solid var(--bizc-hair);font-size:14px;font-weight:600;color:var(--bizc-ink);flex:none}
.bizc-chips{display:flex;gap:6px;flex-wrap:wrap;margin-top:10px}
.bizc-chip{height:34px;border-radius:999px;padding:0 14px;border:1px solid rgba(255,255,255,0.14);background:transparent;font-size:13.5px;font-weight:600;color:var(--bizc-mute);cursor:pointer;font-family:inherit}
.bizc-chip[aria-pressed=true]{background:var(--bizc-ink);color:var(--bizc-canvas);border-color:var(--bizc-ink)}
.bizc-chip[aria-disabled=true]{opacity:.35;cursor:default}
.bizc-xrow{display:flex;align-items:center;gap:12px;min-height:52px;padding:13px 0;border-top:1px solid var(--bizc-hair);width:100%;background:none;border-left:0;border-right:0;border-bottom:0;color:inherit;text-align:left;cursor:pointer;font-family:inherit}
.bizc-xrow:first-child{border-top:0}
.bizc-xrow-text{flex:1;min-width:0}
.bizc-xrow-title{display:block;font-size:15px;font-weight:600;color:var(--bizc-ink)}
.bizc-xrow-sub{display:block;font-size:13px;color:var(--bizc-mute);margin-top:2px}
.bizc-xrow-action{font-size:14px;font-weight:600;color:var(--bizc-mute);flex:none}
.bizc-sheet-scrim{position:fixed;inset:0;background:rgba(0,0,0,0.55);z-index:60}
.bizc-sheet{position:fixed;left:0;right:0;bottom:0;z-index:61;background:#141418;border-top:1px solid rgba(255,255,255,0.1);border-radius:24px 24px 0 0;padding:10px 20px calc(34px + env(safe-area-inset-bottom,0px));max-width:520px;margin:0 auto;max-height:82dvh;overflow-y:auto}
.bizc-sheet-grab{width:36px;height:5px;border-radius:3px;background:rgba(255,255,255,0.22);margin:0 auto 14px}
.bizc-sheet-head{display:flex;align-items:center;justify-content:space-between;gap:12px}
.bizc-sheet-title{font-size:20px;font-weight:700;letter-spacing:-0.02em;color:var(--bizc-ink)}
.bizc-sheet-done{background:none;border:0;font-size:15px;font-weight:600;color:var(--bizc-ink);cursor:pointer;padding:4px 0;font-family:inherit}
.bizc-sheet-sub{font-size:13.5px;color:var(--bizc-mute);margin-top:4px;line-height:1.45}
.bizc-soc-ic{width:30px;height:30px;border-radius:9px;background:var(--bizc-inset);border:1px solid var(--bizc-hair);display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;color:var(--bizc-ink);flex:none}
.bizc-tchip{height:28px;min-width:0;border-radius:8px;background:var(--bizc-inset);border:1px solid var(--bizc-hair);color:var(--bizc-ink);font-size:13.5px;font-variant-numeric:tabular-nums;padding:0 10px;font-family:inherit;color-scheme:dark}
.bizc-switch{width:46px;height:28px;border-radius:999px;border:0;position:relative;flex:none;cursor:pointer;transition:background .15s;background:rgba(255,255,255,0.16)}
.bizc-switch[aria-checked=true]{background:var(--bizc-ink)}
.bizc-switch i{position:absolute;top:3px;left:3px;width:22px;height:22px;border-radius:50%;background:var(--bizc-canvas);transition:left .15s}
.bizc-switch[aria-checked=false] i{background:var(--bizc-ink)}
.bizc-switch[aria-checked=true] i{left:21px;background:var(--bizc-canvas)}
.bizc-day{display:flex;align-items:center;gap:10px;min-height:44px;border-top:1px solid var(--bizc-hair);padding:10px 0;font-size:14.5px}
.bizc-day:first-child{border-top:0}
.bizc-day-name{width:40px;flex:none;font-size:14.5px;font-weight:600;color:var(--bizc-ink)}
.bizc-day-closed{flex:1;font-size:14.5px;color:var(--bizc-dim)}
.bizc-chip:focus-visible,.bizc-xrow:focus-visible,.bizc-sheet-done:focus-visible,.bizc-switch:focus-visible{outline:2px solid #F7931E;outline-offset:2px}

/* BC3: compact the shared phone input into the contact row's dial chip. */
.bizc-phone{flex:1;min-width:0;display:flex;gap:8px;align-items:center}
.bizc-phone button{height:auto!important;border-radius:9px!important;background:var(--bizc-inset)!important;border:1px solid var(--bizc-hair)!important;box-shadow:none!important;font-size:14px;font-weight:600;padding:5px 8px!important}
.bizc-phone button svg{width:14px;height:14px}
.bizc-phone input{flex:1;min-width:0;background:transparent!important;border:0!important;box-shadow:none!important;outline:0;color:var(--bizc-ink);font-size:15px;font-weight:500;padding:0!important;height:auto!important;caret-color:#fff}
.bizc-phone input::placeholder{color:rgba(248,250,252,0.3)}
.bizc-body{overflow-y:auto}

/* BC4 tokens and mock-specific geometry, leaving setup's default cropper untouched. */
.bizc-shell{--bizc-inset:#1E1E23;--bizc-glass:rgba(255,255,255,0.07);--bizc-glass-hair:rgba(255,255,255,0.14);--bizc-destructive:#F87171;--bizc-cover-fade:linear-gradient(180deg,transparent 50%,var(--bizc-card) 100%);height:100dvh;min-height:0}
.bizc-top,.bizc-foot{flex-shrink:0}.bizc-body{min-height:0;will-change:transform}
.bizc-hours-master{border:0;padding:14px 0 6px}
[data-testid="bizc-sheet-hours"] .bizc-rows{margin-top:6px}
.bizc-time-pair{flex:1;display:flex;align-items:center;gap:6px;min-width:0}
.bizc-switch.small{width:38px;height:23px}.bizc-switch.small i{width:17px;height:17px}.bizc-switch.small[aria-checked=true] i{left:18px}
.bizc-minihero{background:var(--bizc-card);border:1px solid var(--bizc-hair);border-radius:18px;overflow:hidden;margin-top:14px}
.bizc-mini-cover{position:relative;height:150px;width:100%;padding:0;border:0;border-radius:0;background:var(--bizc-inset);color:var(--bizc-mute);font-size:13.5px;font-weight:600;gap:8px}
.bizc-mini-cover img{width:100%;height:100%;object-fit:cover;object-position:center;display:block}
.bizc-mini-fade{position:absolute;inset:0;background:var(--bizc-cover-fade);pointer-events:none}
.bizc-mini-identity{position:relative;margin-top:-30px;padding:0 14px 14px;pointer-events:none}
.bizc-mini-crest{width:60px;height:60px;padding:0;border-radius:16px;border:3px solid var(--bizc-card);background:var(--bizc-inset);color:var(--bizc-mute);overflow:hidden;pointer-events:auto}
.bizc-mini-crest img{width:100%;height:100%;object-fit:cover}
.bizc-mini-name{font-size:20px;font-weight:700;letter-spacing:-0.02em;margin-top:10px;overflow-wrap:anywhere}
.bizc-mini-place{font-size:13px;color:var(--bizc-mute);margin-top:3px;overflow-wrap:anywhere}
.bizc-mini-pills{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}
.bizc-mini-pill{display:inline-flex;align-items:center;height:32px;padding:0 14px;border-radius:999px;font-size:13px;font-weight:600;background:var(--bizc-ink);color:var(--bizc-canvas)}
.bizc-mini-pill.glass{background:var(--bizc-glass);border:1px solid var(--bizc-glass-hair);color:var(--bizc-ink)}
.bizc-about{display:block;background:var(--bizc-card);border:1px solid var(--bizc-hair);border-radius:16px;padding:12px 14px;margin-top:10px}
.bizc-about-count{float:right;font-size:11px;font-weight:600;letter-spacing:0;text-transform:none}
.bizc-about textarea{display:block;width:100%;background:transparent;color:var(--bizc-ink);border:0;outline:0;resize:none;font-family:inherit;font-size:14.5px;line-height:1.5;margin-top:6px;padding:0;min-height:22px;overflow:hidden}
.bizc-about textarea::placeholder{color:var(--bizc-dim)}
.bizc-photo-action{display:flex;justify-content:flex-start;width:100%;height:52px;border-radius:16px;background:var(--bizc-card);border:1px solid var(--bizc-hair);padding:0 16px;font-size:15.5px;font-weight:600;color:var(--bizc-ink);margin-top:8px}
.bizc-photo-action.destructive{color:var(--bizc-destructive)}
.welcome-cropper[data-frame-shape=square] .welcome-crop-area{border-radius:4px}
.welcome-cropper[data-appearance=business]{--welcome-mute:rgba(248,250,252,0.62);--welcome-canvas:#0B0B0D}
.welcome-cropper[data-appearance=business] .welcome-cropper-head{top:calc(env(safe-area-inset-top,0px) + 16px)}
.welcome-cropper[data-appearance=business] .welcome-cropper-head span{margin-top:4px}
.welcome-cropper[data-appearance=business] .welcome-cropper-foot p{margin-bottom:36px}
.welcome-cropper[data-appearance=business] .welcome-cropper-foot button{font-size:15.5px}

/* BC5: saved finish keeps the existing frame and miniature, without actions. */
.bizc-shell{--bizc-crest-bg:#E8EEF5;--bizc-crest-ink:#1f2a3a}
.bizc-finish-body h1,.bizc-finish-body .bizc-mini-name{letter-spacing:0}
.bizc-finish-cover{height:110px;display:block}
.bizc-finish-crest{display:flex;align-items:center;justify-content:center;background:var(--bizc-crest-bg);color:var(--bizc-crest-ink);font-size:18px;font-weight:700;flex-shrink:0}
.bizc-finish-note{font-size:13px;line-height:1.45;color:var(--bizc-mute);margin-top:10px}
.bizc-next-label{margin-top:16px}.bizc-next-rows{margin-top:0}
.bizc-next-row{display:flex;align-items:center;justify-content:flex-start;gap:12px;padding:13px 0;border:0;border-top:1px solid var(--bizc-hair);width:100%;height:auto;border-radius:0;white-space:normal;text-align:left;color:var(--bizc-ink);background:none;font-family:inherit}
.bizc-next-row:first-child{border-top:0}.bizc-next-icon{width:34px;height:34px;border-radius:11px;background:var(--bizc-inset);border:1px solid var(--bizc-hair);display:flex;align-items:center;justify-content:center;flex:none}
.bizc-next-icon[data-info=true],.bizc-next-chevron{color:var(--bizc-dim)}
.bizc-next-text{flex:1;min-width:0}.bizc-next-text b{display:block;font-size:15px;font-weight:600}.bizc-next-text>span{display:block;font-size:13px;font-weight:400;color:var(--bizc-mute);margin-top:2px}
.bizc-top:has(.bizc-progress:first-child){min-height:48px}
.bizc-next-row .bizc-next-icon svg{width:17px;height:17px}.bizc-next-row .bizc-next-chevron{width:18px;height:18px}

/* EP5.2 fix: BizcSheet portals to <body>, outside .ep-shell/.bizc-shell. This
   display:contents wrapper re-declares every shell custom property (values
   must equal .ep-shell, .bizc-shell and .ep-settings; a test compares them). */
.bizc-sheet-root{display:contents;--ep-canvas:#0B0B0D;--ep-card:#17171B;--ep-inset:#1E1E23;--ep-hair:rgba(255,255,255,0.08);--ep-ink:#F8FAFC;--ep-mute:rgba(248,250,252,0.62);--ep-dim:rgba(248,250,252,0.42);--ep-progress-missing:rgba(255,255,255,0.12);--ep-chip-ground:rgba(255,255,255,0.07);--ep-chip-hair:rgba(255,255,255,0.14);--ep-settings-danger:#FF6B60;--st2-cell-hair:rgba(255,255,255,0.06);--st2-switch-off:rgba(255,255,255,0.16);--bizc-canvas:#0B0B0D;--bizc-card:#17171B;--bizc-hair:rgba(255,255,255,0.08);--bizc-ink:#F8FAFC;--bizc-mute:rgba(248,250,252,0.62);--bizc-dim:rgba(248,250,252,0.42);--bizc-inset:#1E1E23;--bizc-glass:rgba(255,255,255,0.07);--bizc-glass-hair:rgba(255,255,255,0.14);--bizc-destructive:#F87171;--bizc-cover-fade:linear-gradient(180deg,transparent 50%,var(--bizc-card) 100%);--bizc-crest-bg:#E8EEF5;--bizc-crest-ink:#1f2a3a}

