        const mi = t.mean_index == null ? null : (t.mean_index < 0 ? `+${Math.abs(t.mean_index).toFixed(1)}` : t.mean_index.toFixed(1));
        const num: React.CSSProperties = { fontWeight: 700, textAlign: 'right', fontVariantNumeric: 'tabular-nums' };
        return (
